function moduleData(key){const m={request:[['Reference','Account','Customer','Branch','Book size','Status','Created'],data.requests],inventory:[['Reference','Branch','Book type','Serial range','Total','Available','Status'],data.inventory],issuance:[['Reference','Request','Customer','Branch','Serial range','Status','Processed'],data.issuance],verification:[['Reference','Cheque no.','Account','Customer','Branch','Amount','Status'],data.verifications],stop:[['Reference','Cheque no.','Customer','Branch','Reason','Status','Submitted'],data.stops],returns:[['Reference','Cheque no.','Customer','Branch','Reason','Amount','Status'],data.returns],authorization:[['Queue ID','Transaction','Reference','Customer / Subject','Branch','Maker','Submitted'],data.approvals],vault:[['Reference','Destination branch','Book type','Serial range','Quantity','Status','Dispatched'],data.vault||[]],vaultItems:[['Reference','Customer','Account','Phone','Branch','Request','Status','Dispatched'],data.vaultItems||[]],admin:[['User','Role','Assigned branch','Status','Last active'],adminUsers]};return m[key]?{headers:m[key][0],rows:m[key][1]}:null}
function toast(msg){state.toast=msg;render();setTimeout(()=>{state.toast='';render()},2600)}
function login(){const hero=`<div class="login-hero"><div class="seal seal-lg">${LOGO_BIG}</div><div class="login-tag">✦ Secure banking operations</div><h1>Cheque management, with control at every step.</h1><p>One secure workspace for cheque-book requests, printing, vault control and issuance across every Akuapem Community Bank branch.</p></div>`;const mark=`<div class="bank-mark"><div class="mark-icon">${LOGO_BIG}</div><div>Akuapem Community Bank PLC<br><span>CHEQUE MANAGEMENT SYSTEM</span></div></div>`;const foot=`<div class="login-policy">By signing in you accept the <button class="linklike" onclick="openPolicy()">Login &amp; Acceptable Use Policy</button>. Access is authenticated, recorded in the audit trail, and monitored.</div><div class="powered">© 2026 Akuapem Community Bank PLC · Software © <b>Gyekestone</b>, used under licence.</div>`;const card=state.authView==='forgot'?forgotCard():`<h2>Welcome back</h2><p class="sub">Sign in to your secure operations workspace.</p>${state.loginError?`<div class="login-error">${esc(state.loginError)}</div>`:''}<div class="field"><label>Staff ID or Email</label><input id="login-staff" placeholder="name@acb.com" autocomplete="username" onkeydown="if(event.key==='Enter')signIn()" /></div><div class="field"><label>Password</label><input id="login-password" type="password" autocomplete="current-password" onkeydown="if(event.key==='Enter')signIn()" /></div><button class="primary" onclick="signIn()">Sign in securely →</button><div class="login-row"><button class="linklike" onclick="showForgot()">Forgot password?</button></div><p class="hint">Access is restricted to authorised staff. Your initial password is issued by an administrator — change it after your first sign-in.</p>`;return `<section class="login">${hero}<div class="login-panel"><div class="login-card">${mark}${card}${foot}</div></div></section>`}
function forgotCard(){const f=state.forgot||{step:1};if(f.step===2){return `<h2>Enter reset code</h2><p class="sub">A 6-digit code was sent by SMS to the phone number registered for <b>${esc(f.staffId)}</b>. It expires in 10 minutes.</p>${f.err?`<div class="login-error">${esc(f.err)}</div>`:''}<div class="field"><label>6-digit reset code</label><input id="rs-code" inputmode="numeric" maxlength="6" placeholder="______" autocomplete="one-time-code"></div><div class="field"><label>New password</label><input id="rs-new" type="password" autocomplete="new-password" placeholder="At least 10 characters"></div><div class="field"><label>Confirm new password</label><input id="rs-confirm" type="password" autocomplete="new-password" onkeydown="if(event.key==='Enter')doReset()"></div><button class="primary" onclick="doReset()">Reset password</button><div class="login-row"><button class="linklike" onclick="sendResetCode(true)">Resend code</button><button class="linklike" onclick="showLogin()">Back to sign in</button></div>`}return `<h2>Reset your password</h2><p class="sub">Enter your staff ID. If it matches an active account, a one-time code is sent to the phone number registered for you.</p>${f.err?`<div class="login-error">${esc(f.err)}</div>`:''}<div class="field"><label>Staff ID or Email</label><input id="rs-staff" placeholder="name@acb.com" value="${esc(f.staffId||'')}" autocomplete="username" onkeydown="if(event.key==='Enter')sendResetCode()"></div><button class="primary" onclick="sendResetCode()">Send reset code</button><div class="login-row"><button class="linklike" onclick="showLogin()">Back to sign in</button></div>`}
function showForgot(){state.authView='forgot';state.forgot={step:1,staffId:(val('#login-staff')||'').trim(),msg:'',err:''};state.loginError='';render()}
function showLogin(){state.authView='login';state.forgot={step:1,staffId:'',msg:'',err:''};render()}
async function sendResetCode(resend){const staffId=(state.forgot.step===2?state.forgot.staffId:val('#rs-staff')||'').trim();if(!staffId){state.forgot.err='Enter your staff ID.';render();return}try{const r=await fetch('/api/forgot',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({staffId})});const j=await r.json().catch(()=>({}));if(!r.ok)throw new Error(j.error||'Could not send a code.');state.forgot={step:2,staffId,msg:'',err:''};toast(resend?'If eligible, a new code has been sent.':'If eligible, a reset code has been sent to your phone.')}catch(e){state.forgot.err=e.message||'Could not send a code.'}render()}
async function doReset(){const code=val('#rs-code');const np=document.querySelector('#rs-new').value;const cf=document.querySelector('#rs-confirm').value;if(np.length<10){state.forgot.err='New password must be at least 10 characters.';render();return}if(np!==cf){state.forgot.err='The two passwords do not match.';render();return}try{const r=await fetch('/api/reset',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({staffId:state.forgot.staffId,code,newPassword:np})});const j=await r.json().catch(()=>({}));if(!r.ok)throw new Error(j.error||'Could not reset password.');state.authView='login';state.forgot={step:1,staffId:'',msg:'',err:''};state.loginError='';toast('Password reset. Please sign in with your new password.')}catch(e){state.forgot.err=e.message||'Could not reset password.'}render()}
function sidebar(){return `<aside class="sidebar"><div class="brand"><div class="brand-logo">${LOGO}</div><div><b>Akuapem Community<br>Bank PLC</b><br><span>CHEQUE MANAGEMENT</span></div></div><div class="nav-label">WORKSPACE</div>${nav.slice(0,-3).map(n=>`<button class="nav-btn ${state.page===n[0]?'active':''}" onclick="go('${n[0]}')" title="${esc(n[2])}"><b>${n[1]}</b><span>${n[2]}</span></button>`).join('')}<div class="nav-label">GOVERNANCE</div>${nav.slice(-3).map(n=>`<button class="nav-btn ${state.page===n[0]?'active':''}" onclick="go('${n[0]}')" title="${esc(n[2])}"><b>${n[1]}</b><span>${n[2]}</span></button>`).join('')}<div class="sidebar-foot">Secure session<br>v1.0 Prototype</div></aside>`}
function topbar(){let global=state.global;return `<header class="topbar"><button class="ghost mobile-menu" onclick="document.querySelector('.sidebar').classList.toggle('open')">☰</button><span class="scope-pill">${global?'Global view · all six branches':`Branch view · ${state.branch}`}</span><div class="top-controls"><select onchange="setBranch(this.value)" ${global?'':'disabled'}>${global?'<option value="All Branches">All branches</option>':''}${branches.map(b=>`<option ${b===state.branch?'selected':''}>${b}</option>`).join('')}</select><div class="user-block"><div class="avatar">${state.initials}</div><div><div class="user-name">${esc(state.user||state.role)}</div><div class="user-role">${esc(state.role)}</div></div></div><button class="ghost" onclick="openPw()" title="Change password">🔑</button><button class="ghost" onclick="logout()">Sign out</button></div></header>`}
function shell(content,title,eyebrow='OPERATIONS'){return `<div class="app-shell">${sidebar()}<div class="content">${topbar()}<div class="page-wrap"><div class="title-row"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1></div></div>${content}</div></div></div>${state.modal?modal():''}${state.confirm?confirmDialog():''}${state.toast?`<div class="toast">✓ ${state.toast}</div>`:''}`}
function moMonthly(rows,idx){const now=new Date();const buckets=[];const map={};for(let i=5;i>=0;i--){const d=new Date(now.getFullYear(),now.getMonth()-i,1);const k=d.getFullYear()+'-'+d.getMonth();buckets.push({k,label:d.toLocaleString('en',{month:'short'})});map[k]=0}(rows||[]).forEach(r=>{const t=repParseDate(r[idx]);if(!t)return;const k=t.getFullYear()+'-'+t.getMonth();if(k in map)map[k]++});return {points:buckets.map(b=>map[b.k]),labels:buckets.map(b=>b.label)}}
function momChange(points){const a=points[points.length-2]||0,b=points[points.length-1]||0;if(!a&&!b)return null;if(!a)return {pct:100,up:true};const p=Math.round((b-a)/a*100);return {pct:Math.abs(p),up:p>=0}}
function momBadge(m){return m?`<span class="stat-badge ${m.up?'up':'down'}">${m.up?'▲':'▼'} ${m.pct}%</span>`:'<span class="stat-badge flat">—</span>'}
function areaChartSvg(points,labels){const w=640,h=210,pad=26;const max=Math.max(1,...points);const n=points.length;const X=i=>pad+i*(w-2*pad)/Math.max(1,n-1);const Y=v=>h-pad-(v/max)*(h-2*pad);const pts=points.map((v,i)=>`${X(i).toFixed(1)},${Y(v).toFixed(1)}`).join(' ');const poly=`${pad},${(h-pad).toFixed(1)} ${pts} ${(w-pad).toFixed(1)},${(h-pad).toFixed(1)}`;return `<div class="area-wrap"><svg viewBox="0 0 ${w} ${h}" preserveAspectRatio="none" class="area-svg"><defs><linearGradient id="acbArea" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#1669a9" stop-opacity="0.35"/><stop offset="100%" stop-color="#1669a9" stop-opacity="0.02"/></linearGradient></defs><polygon points="${poly}" fill="url(#acbArea)"/><polyline points="${pts}" fill="none" stroke="#0d416f" stroke-width="2.5" stroke-linejoin="round"/>${points.map((v,i)=>`<circle cx="${X(i).toFixed(1)}" cy="${Y(v).toFixed(1)}" r="3.5" fill="#fff" stroke="#0d416f" stroke-width="2"/>`).join('')}</svg><div class="area-x">${labels.map(l=>`<span>${esc(l)}</span>`).join('')}</div></div>`}
function advancedStats(){const reqs=(data.requests||[]).filter(allowed),iss=(data.issuance||[]).filter(allowed),inv=(data.inventory||[]).filter(allowed),appr=(data.approvals||[]).filter(allowed);const batches=(data.printBatches||[]).filter(b=>state.global||b.branch===state.branch);const inVaultBooks=batches.filter(b=>b.status==='In Branch Vault').reduce((n,b)=>n+((b.items||[]).length),0);const series=moMonthly(reqs,6);const mom=momChange(series.points);const issMom=momChange(moMonthly(iss,6).points);const leaves=inv.reduce((n,r)=>n+(parseInt(r[5],10)||0),0);const progressed=reqs.filter(r=>!/pending|reject/i.test(r[5])).length;const rate=reqs.length?Math.round(progressed/reqs.length*100):0;const kpis=[['Cheque requisitions',reqs.length.toLocaleString(),momBadge(mom),'requisitions'],['Cheque books issued',iss.length.toLocaleString(),momBadge(issMom),'issued'],['Leaves available',leaves.toLocaleString(),`<span class="stat-badge flat">${inv.length} range${inv.length===1?'':'s'}</span>`,'leaves'],['Books in branch vault',inVaultBooks.toLocaleString(),`<span class="stat-badge flat">${batches.length} batch${batches.length===1?'':'es'}</span>`,'vault']];return `<div class="grid adv-mid"><section class="card adv-chart reveal clickable" onclick="dashDetail('requisitions')" title="Click for details" style="--d:0ms"><div class="card-head"><div><h3>Cheque requisition trend</h3><small>Last 6 months · ${esc(state.global?'all branches':state.branch)}</small></div>${momBadge(mom)}</div>${areaChartSvg(series.points,series.labels)}</section><div class="adv-side"><section class="card adv-goal reveal clickable" onclick="dashDetail('progressed')" title="Click for details" style="--d:90ms"><div><p class="adv-eyebrow">Primary goal</p><h4>Requisitions progressed</h4></div><div class="adv-goal-foot"><div class="adv-goal-row"><span class="adv-goal-pct">${rate}%</span><span class="adv-goal-target">Target: 90%</span></div><div class="adv-goal-track"><div class="adv-goal-fill" style="width:${Math.min(100,rate)}%"></div></div></div></section><section class="card adv-info reveal clickable" onclick="dashDetail('pending')" title="Click for details" style="--d:180ms"><div class="adv-info-head"><div class="adv-info-icon">◉</div><h4>Authorisation load</h4></div><p class="adv-info-text"><b>${appr.length}</b> item${appr.length===1?'':'s'} awaiting authorisation${appr.length?'':' — all clear'}.</p><span class="kpi-more">View details →</span></section></div></div><div class="grid kpis adv-kpis">${kpis.map((k,i)=>`<div class="card kpi reveal clickable" onclick="dashDetail('${k[3]}')" title="Click for details" style="--d:${240+i*70}ms"><p class="kpi-label">${k[0]}</p><div class="stat-row"><p class="stat-value">${k[1]}</p>${k[2]}</div><span class="kpi-more">View details →</span></div>`).join('')}</div>`}
function dashboard(){const records=(data.requests||[]).filter(allowed);const appr=(data.approvals||[]).filter(allowed);const batches=(data.printBatches||[]).filter(b=>state.global||b.branch===state.branch);const toAccept=batches.filter(b=>b.status==='In Transit to Branch'||b.status==='Pending Branch Authorisation');const inProd=batches.filter(b=>['Submitted to Head Office','Sent for Printing','In Head-Office Vault'].includes(b.status));const alerts=[];const dueDestruction=agingItems().filter(i=>i.age>=AGING_LIMIT_DAYS&&i.kind==='Uncollected book');if(dueDestruction.length)alerts.push(['⛔',`${dueDestruction.length} cheque book${dueDestruction.length===1?'':'s'} due for destruction`,'Uncollected for over a year and auto-archived. Review and arrange destruction under dual control.',"state.page='reports';state.reportTab='aging';render()"]);if(appr.length)alerts.push(['⚠',`${appr.length} item${appr.length===1?'':'s'} awaiting authorisation`,'Review in the authorisation queue.',"go('authorization')"]);if(toAccept.length)alerts.push(['▦',`${toAccept.length} cheque-book batch${toAccept.length===1?'':'es'} awaiting branch acceptance`,'Confirm &amp; authorise in Vault &amp; Cheque Production.',"go('vault')"]);if(inProd.length)alerts.push(['◷',`${inProd.length} batch${inProd.length===1?'':'es'} in production`,'At head office for printing / serialising.',"go('vault')"]);const alertHtml=alerts.length?alerts.map(a=>`<div class="alert clickable" onclick="${a[3]}"><div class="alert-icon">${a[0]}</div><div><b>${esc(a[1])}</b><p>${esc(a[2])}</p></div><span class="alert-go">›</span></div>`).join(''):'<p class="ok-note">✓ No exceptions in your scope.</p>';return shell(advancedStats()+`<div class="grid bottom-grid" style="margin-top:18px"><section class="card wide-card reveal" style="--d:300ms"><div class="card-head"><div><h3>Recent cheque book requests</h3><small>Live activity within your scope · click a row for details</small></div><button class="ghost" onclick="go('request')">Manage requests</button></div>${recentReqTable(records)}</section><section class="card reveal" style="--d:360ms"><div class="card-head"><div><h3>Priority alerts</h3><small>Exceptions needing attention</small></div><button class="ghost" onclick="go('authorization')">View all</button></div>${alertHtml}<div class="quick" style="margin-top:14px"><button onclick="go('request')">＋ New request<span>Initiate cheque book request</span></button><button onclick="go('vault')">▦ Production<span>Cheque batch pipeline</span></button><button onclick="go('reports')">▥ Analytics<span>Filter &amp; group activity</span></button><button onclick="go('authorization')">◉ Review queue<span>Maker-checker approvals</span></button></div></section></div>`,`Overview`)}
function modulePage(key,title,headers,rows,opts={}){const create=opts.create;const action=opts.action;return shell(`<div class="module-toolbar"><div class="filters"><input class="search" placeholder="Search ${title.toLowerCase()}" oninput="filterTable(this.value)"><span class="module-summary">Showing <strong>${rows.filter(allowed).length}</strong> records</span></div>${create&&has(`${key}.create`)?`<button class="primary" onclick="openForm('${key}')">${create.label}</button>`:''}</div><section class="card wide-card"><div class="card-head"><div><h3>${title}</h3><small>${state.global?'All branches':'Your assigned branch only'}</small></div></div>${table(headers,rows,action?`<button class="ghost row-action" onclick="rowAction('${key}',{i})">${action}</button>`:'')}</section>`,title,opts.eyebrow||'CHEQUE OPERATIONS')}
function customers(){if(!has('customers.view'))return shell(`<div class="denied"><b>Customer search restricted</b><br>Your profile does not include permission to search the customer database.</div>`,'Customer & Account Search','CUSTOMER SERVICE');return shell(`<div class="card form-card"><div class="card-head"><div><h3>Find a customer or account</h3><small>Search the customer database by account number or name, then use the result to start a cheque book request.</small></div></div><div class="form-grid"><div class="field"><label>Account number or name</label><input id="customer-q" placeholder="e.g. 1140000030 or Ama Ofori" onkeydown="if(event.key==='Enter')customerSearch()" /></div></div><div class="form-actions"><button class="primary" onclick="customerSearch()">Search database</button></div></div><div id="customer-result"></div>`,`Customer & Account Search`,'CUSTOMER SERVICE')}
function branchField(){const global=state.global;const current=branches.includes(state.branch)?state.branch:branches[0];return global?`<select data-field="branch">${branches.map(b=>`<option ${b===current?'selected':''}>${b}</option>`).join('')}</select>`:`<input data-field="branch" value="${esc(state.branch)}" readonly>`}
function form(key){const cfg={request:['New Cheque Book Request','Collection branch',[['account','Customer account','AC-00129482'],['customer','Customer name','Ama Ofori'],['phone','Customer phone (e.g. 0244000000)',''],['book','Book size','50 leaves'],['reason','Reason','New account cheque book']]],inventory:['Register Cheque Range','Branch',[['type','Cheque book type','ACB Standard'],['start','Start serial','160001'],['end','End serial','160500'],['supplier','Supplier / batch','SecurePrint Ghana Ltd']]],issuance:['Issue Cheque Book','Issuing branch',[['request','Approved request reference','CBR-2026-0841'],['account','Customer account','AC-00129482'],['range','Cheque serial range','120151 – 120200'],['method','Collection method','In-person collection'],['verifier','Identity verified by','Yaw Sarpong']]]}[key];if(!cfg)return '';const [title,branchLabel,fields]=cfg;const pf=(key==='request'&&state.prefill)?state.prefill:{};return shell(`<section class="card form-card"><div class="card-head"><div><h3>${title}</h3><small>Transactions are captured by a maker and routed for authorisation when required.</small></div></div><div class="notice">${key==='request'&&state.prefill?'Customer details pre-filled from the customer database. ':''}You are operating within <b>${state.global?'the selected global scope':state.branch}</b>. All actions will be logged with your role, date and time.</div><form id="txn-form" onsubmit="return false" class="form-grid"><div class="field"><label>${branchLabel}</label>${branchField()}</div>${fields.map(([k,l,v])=>`<div class="field"><label>${l}</label><input data-field="${k}" value="${esc(pf[k]!==undefined?pf[k]:v)}"></div>`).join('')}</form><div class="form-actions"><button class="ghost" onclick="go('${key}')">Cancel</button><button class="primary" onclick="submitForm('${key}')">Submit ${key==='issuance'?'issuance':key==='returns'?'return record':'for authorisation'} →</button></div></section>`,title,'NEW TRANSACTION')}
function authorization(){if(!has('txn.authorise')) return shell(`<div class="denied"><b>Authorisation queue restricted</b><br>Your ${state.role} profile can submit transactions but cannot approve them. Please contact your Branch Manager or Head Office.</div>`,`Authorization Queue`,'MAKER–CHECKER CONTROL');return modulePage('authorization','Authorization Queue',['Queue ID','Transaction','Reference','Customer / Subject','Branch','Maker','Submitted'],data.approvals,{action:'Review',eyebrow:'MAKER–CHECKER CONTROL'})}
function setReportTab(t){state.reportTab=t;if(t==='system')loadSystemLog();else render()}
function exportCsv(name,headers,rows){const q=c=>`"${String(c==null?'':c).replace(/"/g,'""')}"`;const csv=[headers.map(q).join(',')].concat(rows.map(r=>r.map(q).join(','))).join('\r\n');const blob=new Blob(['﻿'+csv],{type:'text/csv;charset=utf-8'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name+'-'+new Date().toISOString().slice(0,10)+'.csv';document.body.appendChild(a);a.click();setTimeout(()=>{URL.revokeObjectURL(a.href);a.remove()},500);toast('CSV exported.')}
async function loadSystemLog(){try{const f=state.logFilter||{};const p=new URLSearchParams();if(f.level)p.set('level',f.level);if(f.q)p.set('q',f.q);const r=await fetch('/api/reports/system-log?'+p.toString());const j=await r.json().catch(()=>({}));if(!r.ok)throw new Error(j.error||'Failed');state.systemLog=j.rows||[]}catch(e){state.systemLog=[];toast(e.message||'Could not load system log.')}render()}
function exportAccessCsv(){const dir=data.directory||{};const rows=Object.entries(dir).map(([id,u])=>{const set=effPermsClient(u.role,u.groups);const v=sodViolation(set);return [u.name,id,u.role,(u.groups||[]).join('; ')||'—',[...set].join('; '),u.status,u.lastReviewed||'—',v?`${v[0]} vs ${v[1]}`:'']});exportCsv('user-access',['User','Staff ID','Role','Groups','Permissions','Status','Last reviewed','SoD conflict'],rows)}
function reports(){const tabs=[];if(has('reports.view'))tabs.push(['operational','Operational']);if(has('reports.view'))tabs.push(['aging','Aging & SLA']);if(has('reports.view'))tabs.push(['reconciliation','Reconciliation']);if(has('reports.view'))tabs.push(['tat','Turnaround']);if(has('reports.view'))tabs.push(['returns','Branch Returns']);if(has('reports.view'))tabs.push(['destruction','Destruction']);if(has('admin.manage'))tabs.push(['exceptions','Control Exceptions']);if(has('audit.view'))tabs.push(['audit','Audit Trail']);if(has('logs.view'))tabs.push(['system','System Log']);if(has('admin.manage'))tabs.push(['access','User Access & Groups']);if(!tabs.length)return shell(`<div class="denied"><b>Reports restricted</b><br>Your profile does not include reporting permissions.</div>`,'Reports & Insights','MANAGEMENT INFORMATION');let tab=state.reportTab;if(!tabs.some(t=>t[0]===tab))tab=tabs[0][0];const nav=`<div class="admin-tabs">${tabs.map(t=>`<button class="admin-tab ${tab===t[0]?'active':''}" onclick="setReportTab('${t[0]}')">${t[1]}</button>`).join('')}</div>`;const views={operational:reportOperational,aging:reportAging,reconciliation:reportReconciliation,tat:reportTat,returns:reportReturns,destruction:reportDestruction,exceptions:reportExceptions,audit:reportAudit,system:reportSystem,access:reportAccess};return shell(nav+(views[tab]||reportOperational)(),'Reports & Insights','MANAGEMENT INFORMATION')}
function repItems(){const f=state.repFilter||{};const myRefs=f.mine?new Set((data.audit||[]).filter(a=>a[3]===state.user).map(a=>a[2])):null;const out=[];const add=(type,ref,subject,branch,status,date)=>{if(!state.global&&branch!==state.branch)return;if(myRefs&&!myRefs.has(ref))return;out.push({type,ref,subject:subject||'—',branch:branch||'—',status:status||'—',date:date||''})};(data.requests||[]).forEach(r=>add('Requisition',r[0],r[2],r[3],r[5],r[6]));(data.issuance||[]).forEach(r=>add('Issuance',r[0],r[2],r[3],r[5],r[6]));(data.inventory||[]).forEach(r=>add('Inventory',r[0],r[2],r[1],r[6],''));(data.printBatches||[]).forEach(b=>add('Print batch',b.id,((b.items||[]).length)+' book(s)',b.branch,b.status,b.createdAt));return out}
function repParseDate(s){if(!s)return null;const d=new Date(String(s).replace(',',''));return isNaN(d.getTime())?null:d}
function repFiltered(){const f=state.repFilter||{};let items=repItems();if(f.type)items=items.filter(i=>i.type===f.type);if(f.status)items=items.filter(i=>i.status===f.status);if(f.branch)items=items.filter(i=>i.branch===f.branch);if(f.from){const d=new Date(f.from);items=items.filter(i=>{const t=repParseDate(i.date);return !t||t>=d})}if(f.to){const d=new Date(f.to);d.setHours(23,59,59,999);items=items.filter(i=>{const t=repParseDate(i.date);return !t||t<=d})}return items}
function repGroup(items,key){const m=new Map();items.forEach(i=>{const k=i[key]||'—';m.set(k,(m.get(k)||0)+1)});return [...m.entries()].sort((a,b)=>b[1]-a[1])}
function repSet(k,v){state.repFilter={...(state.repFilter||{}),[k]:v};render()}
function repReset(){const g=(state.repFilter||{}).groupBy||'type';state.repFilter={from:'',to:'',branch:'',type:'',status:'',mine:false,groupBy:g};render()}
function repExport(){const items=repFiltered();exportCsv('operations-report',['Type','Reference','Subject','Branch','Status','Date'],items.map(i=>[i.type,i.ref,i.subject,i.branch,i.status,i.date]))}
function reportOperational(){const f=state.repFilter||(state.repFilter={from:'',to:'',branch:'',type:'',status:'',mine:false,groupBy:'type'});const allItems=repItems();const items=repFiltered();const types=[...new Set(allItems.map(i=>i.type))].sort();const statuses=[...new Set(allItems.map(i=>i.status))].sort();const gk=f.groupBy||'type';const groups=repGroup(items,gk);const maxC=Math.max(1,...groups.map(g=>g[1]));const total=items.length;const isAdverse=s=>/reject|return|stopped|cancel/i.test(s);const isPending=s=>/pending|awaiting|transit|submitted|printing|head-office/i.test(s);const pending=items.filter(i=>!isAdverse(i.status)&&isPending(i.status)).length;const done=items.filter(i=>!isAdverse(i.status)&&!isPending(i.status)&&/authorized|authorised|active|accepted|issued|ready|collected|branch vault/i.test(i.status)).length;const adverse=items.filter(i=>isAdverse(i.status)).length;const kpi=(label,val,cls,icon)=>`<div class="card kpi"><div><div class="kpi-label">${label}</div><strong>${val}</strong><small>Current filter</small></div><div class="metric-icon ${cls||''}">${icon}</div></div>`;const kpis=`<div class="grid kpis">${kpi('Items in view',total.toLocaleString(),'','▤')}${kpi('Pending / in-flight',pending.toLocaleString(),'gold','◷')}${kpi('Completed',done.toLocaleString(),'green','✓')}${kpi('Returned / stopped',adverse.toLocaleString(),'red','↩')}</div>`;const branchSel=state.global?`<select onchange="repSet('branch',this.value)"><option value="">All branches</option>${branches.map(b=>`<option ${f.branch===b?'selected':''}>${esc(b)}</option>`).join('')}</select>`:`<span class="rep-scope">${esc(state.branch)}</span>`;const filterBar=`<div class="rep-filters"><label>From <input type="date" value="${esc(f.from||'')}" onchange="repSet('from',this.value)"></label><label>To <input type="date" value="${esc(f.to||'')}" onchange="repSet('to',this.value)"></label>${branchSel}<select onchange="repSet('type',this.value)"><option value="">All types</option>${types.map(t=>`<option ${f.type===t?'selected':''}>${esc(t)}</option>`).join('')}</select><select onchange="repSet('status',this.value)"><option value="">All statuses</option>${statuses.map(s=>`<option ${f.status===s?'selected':''}>${esc(s)}</option>`).join('')}</select><select onchange="repSet('groupBy',this.value)">${[['type','Type'],['branch','Branch'],['status','Status']].map(o=>`<option value="${o[0]}" ${gk===o[0]?'selected':''}>Group by ${o[1]}</option>`).join('')}</select><label class="rep-toggle"><input type="checkbox" ${f.mine?'checked':''} onchange="repSet('mine',this.checked)"> My items only</label><button class="ghost xs" onclick="repReset()">Reset</button></div>`;const chart=groups.length?`<div class="rep-chart">${groups.map(g=>`<div class="rep-bar-row"><span class="rep-bar-label" title="${esc(g[0])}">${esc(g[0])}</span><div class="rep-bar-track"><div class="rep-bar-fill" style="width:${Math.round(g[1]/maxC*100)}%"></div></div><span class="rep-bar-val">${g[1]} · ${total?Math.round(g[1]/total*100):0}%</span></div>`).join('')}</div>`:'<p class="empty">No items match these filters.</p>';const detail=items.slice(0,200).map(i=>`<tr><td>${esc(i.type)}</td><td><b>${esc(i.ref)}</b></td><td>${esc(i.subject)}</td><td>${esc(i.branch)}</td><td>${badge(i.status)}</td><td>${esc(i.date||'—')}</td></tr>`).join('')||'<tr><td colspan="6" class="empty">No items match these filters.</td></tr>';return `${kpis}<section class="card wide-card"><div class="card-head"><div><h3>Operations analytics</h3><small>Live activity across ${state.global?'all branches':'your branch'} — filter, group and export. Date filter uses each record's own timestamp.</small></div><button class="ghost" onclick="repExport()">Export CSV</button></div>${filterBar}<div class="card-head" style="margin-top:6px"><div><h4 style="margin:0;font-size:13px">Breakdown by ${gk} — ${total.toLocaleString()} item${total===1?'':'s'}</h4></div></div>${chart}</section><section class="card wide-card" style="margin-top:18px"><div class="card-head"><div><h3>Detail</h3><small>Up to 200 rows in the current filter</small></div></div><div class="table-wrap"><table><thead><tr><th>Type</th><th>Reference</th><th>Subject</th><th>Branch</th><th>Status</th><th>Date</th></tr></thead><tbody>${detail}</tbody></table></div></section>`}
// ---- Cheque-book aging (policy: 1 year to destruction) ----
const AGING_LIMIT_DAYS=365; // open/uncollected items older than this are auto-moved to the Aging Bin (due for destruction)
function daysSince(str){const d=repParseDate(str);if(!d)return null;return Math.floor((Date.now()-d.getTime())/86400000)}
function ageLabel(a){if(a==null)return '—';if(a>=365){const y=Math.floor(a/365),d=a%365;return `${y}y ${d}d`}return `${a}d`}
function readyDateMap(){const m={};(data.printBatches||[]).forEach(b=>{const acc=(b.log||[]).find(l=>/branch vault/i.test(l[2]));const dt=acc?acc[0]:b.createdAt;(b.items||[]).forEach(it=>{if(it.reqRef)m[it.reqRef]=dt})});return m}
function agingItems(){const rdm=readyDateMap();const openReq=/^(pending|authorized|authorised|in print batch)/i;const out=[];(data.requests||[]).forEach(r=>{if(!allowed(r))return;const status=String(r[5]||'');const ready=/ready for issuance/i.test(status);const open=openReq.test(status);if(!ready&&!open)return;const since=ready?(rdm[r[0]]||r[6]):r[6];const age=daysSince(since);if(age==null||age<0||age>7300)return;/* ignore unparseable/legacy dates (>20y) so a data artefact can't raise a false destruction flag */out.push({ref:r[0],account:r[1],customer:r[2],branch:r[3],book:r[4],status,kind:ready?'Uncollected book':'Open request',since,age})});return out.sort((a,b)=>b.age-a.age)}
function agingBucket(age){if(age>=AGING_LIMIT_DAYS)return['Archived','arch'];if(age>=181)return['181–364 days','red'];if(age>=91)return['91–180 days','orange'];if(age>=31)return['31–90 days','amber'];return['0–30 days','green']}
function agingDisposition(i){return i.age<AGING_LIMIT_DAYS?'Active':(i.kind==='Uncollected book'?'Due for destruction':'Stale — archived')}
function agingExport(which){const items=agingItems();const list=which==='bin'?items.filter(i=>i.age>=AGING_LIMIT_DAYS):items.filter(i=>i.age<AGING_LIMIT_DAYS);exportCsv(which==='bin'?'aging-bin-destruction':'aging-sla',['Kind','Reference','Account','Customer','Branch','Book','Status','Age (days)','Since','Disposition'],list.map(i=>[i.kind,i.ref,i.account,i.customer,i.branch,i.book,i.status,i.age,i.since,agingDisposition(i)]))}
function reportAging(){const items=agingItems();const active=items.filter(i=>i.age<AGING_LIMIT_DAYS);const bin=items.filter(i=>i.age>=AGING_LIMIT_DAYS);const destr=bin.filter(i=>i.kind==='Uncollected book');const overdue=active.filter(i=>i.age>=91);const kpi=(label,val,cls,icon,sub)=>`<div class="card kpi"><div><div class="kpi-label">${label}</div><strong>${val}</strong><small>${sub||'In your scope'}</small></div><div class="metric-icon ${cls||''}">${icon}</div></div>`;const kpis=`<div class="grid kpis">${kpi('Open &amp; uncollected',active.length.toLocaleString(),'','▤','Active, under 1 year')}${kpi('Overdue (&gt;90 days)',overdue.length.toLocaleString(),'gold','◷','Needs follow-up')}${kpi('In aging bin (≥1yr)',bin.length.toLocaleString(),'red','🗄','Auto-archived')}${kpi('Due for destruction',destr.length.toLocaleString(),'red','⛔','Uncollected books ≥ 1 year')}</div>`;const order=[['0–30 days','green'],['31–90 days','amber'],['91–180 days','orange'],['181–364 days','red']];const counts={};active.forEach(i=>{const b=agingBucket(i.age)[0];counts[b]=(counts[b]||0)+1});const maxC=Math.max(1,...order.map(o=>counts[o[0]]||0));const chart=`<div class="rep-chart">${order.map(o=>{const c=counts[o[0]]||0;return `<div class="rep-bar-row"><span class="rep-bar-label">${o[0]}</span><div class="rep-bar-track"><div class="rep-bar-fill rag-${o[1]}" style="width:${Math.round((c/maxC)*100)}%"></div></div><span class="rep-bar-val">${c} · ${active.length?Math.round(c/active.length*100):0}%</span></div>`}).join('')}</div>`;const activeRows=active.length?active.map(i=>`<tr><td>${esc(i.kind)}</td><td><b>${esc(i.ref)}</b></td><td>${esc(i.account)}</td><td>${esc(i.customer)}</td><td>${esc(i.branch)}</td><td>${esc(i.book)}</td><td>${badge(i.status)}</td><td><b>${ageLabel(i.age)}</b></td></tr>`).join(''):'<tr><td colspan="8" class="empty">No open or uncollected items in scope.</td></tr>';const binRows=bin.length?bin.map(i=>`<tr><td><b>${esc(i.ref)}</b></td><td>${esc(i.account)}</td><td>${esc(i.customer)}</td><td>${esc(i.branch)}</td><td>${esc(i.book)}</td><td><b>${ageLabel(i.age)}</b></td><td>${esc(i.since||'—')}</td><td>${i.kind==='Uncollected book'?'<span class="badge stopped">Due for destruction</span>':'<span class="badge draft">Stale — archived</span>'}</td><td>${i.kind==='Uncollected book'&&has('vault.authorise')?`<button class="ghost xs danger" onclick="destroyBook('${esc(i.ref)}')">Destroy…</button>`:''}</td></tr>`).join(''):'<tr><td colspan="9" class="empty">Nothing has reached the 1-year aging limit.</td></tr>';return `${kpis}<section class="card wide-card"><div class="card-head"><div><h3>Aging &amp; SLA — open and uncollected cheque books</h3><small>Policy: items open or uncollected for 1 year (${AGING_LIMIT_DAYS} days) are auto-moved to the Aging Bin. Age is measured from arrival at the branch for printed books, otherwise from the request date.</small></div><button class="ghost" onclick="agingExport('active')">Export CSV</button></div><div class="card-head" style="margin-top:2px"><div><h4 style="margin:0;font-size:13px">Aging profile — ${active.length.toLocaleString()} active item${active.length===1?'':'s'}</h4></div></div>${chart}<div class="table-wrap" style="margin-top:8px"><table><thead><tr><th>Kind</th><th>Reference</th><th>Account</th><th>Customer</th><th>Branch</th><th>Book</th><th>Status</th><th>Age</th></tr></thead><tbody>${activeRows}</tbody></table></div></section><section class="card wide-card" style="margin-top:18px"><div class="card-head"><div><h3>🗄 Aging Bin / Archive — ${bin.length.toLocaleString()} item${bin.length===1?'':'s'} ≥ 1 year</h3><small>Automatically archived at the 1-year mark. Uncollected books shown here are due for destruction under dual control — record a destruction certificate before disposal.</small></div><button class="ghost" onclick="agingExport('bin')">Export bin CSV</button></div><div class="table-wrap"><table><thead><tr><th>Reference</th><th>Account</th><th>Customer</th><th>Branch</th><th>Book</th><th>Aged</th><th>Since</th><th>Disposition</th><th></th></tr></thead><tbody>${binRows}</tbody></table></div></section>`}
// ---- Shared reporting helpers ----
function num(x){const n=parseInt(String(x==null?'':x).replace(/[^\d-]/g,''),10);return Number.isFinite(n)?n:0}
function leavesFromRange(s){const m=String(s||'').match(/(\d+)\s*[–—-]\s*(\d+)/);if(m)return Math.abs(parseInt(m[2],10)-parseInt(m[1],10))+1;return 0}
function scopeBranches(){return state.global?(state.branch==='All Branches'?branches.slice():[state.branch]):[state.branch]}
function repKpi(label,val,cls,icon,sub){return `<div class="card kpi"><div><div class="kpi-label">${label}</div><strong>${val}</strong><small>${sub||'In your scope'}</small></div><div class="metric-icon ${cls||''}">${icon}</div></div>`}
function todayISO(){return new Date().toISOString().slice(0,10)}
function monthStart(){const d=new Date();return new Date(d.getFullYear(),d.getMonth(),1).toISOString().slice(0,10)}

// ---- Serial-stock reconciliation + stock cover ----
function reconRows(){const inv=(data.inventory||[]).filter(allowed);const iss=(data.issuance||[]).filter(allowed);const by={};const ens=b=>by[b]||(by[b]={branch:b,ranges:0,received:0,onHand:0,issued:0});inv.forEach(r=>{const g=ens(r[1]);g.ranges++;g.received+=num(r[4]);g.onHand+=num(r[5])});iss.forEach(r=>{ens(r[3]).issued+=leavesFromRange(r[4])});return Object.values(by).map(g=>{g.expected=g.received-g.issued;g.variance=g.onHand-g.expected;return g}).sort((a,b)=>a.branch.localeCompare(b.branch))}
function stockCover(){const inv=(data.inventory||[]).filter(allowed);const iss=(data.issuance||[]).filter(allowed);const cutoff=Date.now()-90*86400000;const by={};const ens=b=>by[b]||(by[b]={branch:b,onHand:0,recent:0});inv.forEach(r=>ens(r[1]).onHand+=num(r[5]));iss.forEach(r=>{const d=repParseDate(r[6]);if(d&&d.getTime()>=cutoff&&(Date.now()-d.getTime())<7300*86400000)ens(r[3]).recent+=leavesFromRange(r[4])});return Object.values(by).map(c=>{c.perMonth=c.recent?Math.round(c.recent/3):0;c.months=!c.perMonth?(c.onHand>0?Infinity:null):c.onHand/c.perMonth;c.flag=c.months==null?'<span class="badge draft">No stock</span>':c.months===Infinity?'<span class="badge active">Ample</span>':c.months<1?'<span class="badge stopped">Reorder now</span>':c.months<2?'<span class="badge pending">Reorder soon</span>':'<span class="badge active">OK</span>';return c}).sort((a,b)=>a.branch.localeCompare(b.branch))}
function reconExport(){exportCsv('serial-stock-reconciliation',['Branch','Ranges','Received','Issued','On hand','Expected','Variance'],reconRows().map(g=>[g.branch,g.ranges,g.received,g.issued,g.onHand,g.expected,g.variance]))}
function reportReconciliation(){const rows=reconRows();const tot=rows.reduce((a,g)=>({ranges:a.ranges+g.ranges,received:a.received+g.received,issued:a.issued+g.issued,onHand:a.onHand+g.onHand,expected:a.expected+g.expected,variance:a.variance+g.variance}),{ranges:0,received:0,issued:0,onHand:0,expected:0,variance:0});const flagged=rows.filter(g=>g.variance!==0).length;const kpis=`<div class="grid kpis">${repKpi('Leaves received',tot.received.toLocaleString(),'','▤','Into branch vaults')}${repKpi('Leaves issued',tot.issued.toLocaleString(),'green','✓','Recorded issuances')}${repKpi('On hand (book)',tot.onHand.toLocaleString(),'gold','▦','Should be in vault')}${repKpi('Branches with variance',flagged.toLocaleString(),flagged?'red':'green',flagged?'⚠':'✓','Unaccounted leaves')}</div>`;const vcell=v=>v===0?'<span class="badge active">Reconciled</span>':`<span class="badge stopped">${v>0?'+':''}${v.toLocaleString()}</span>`;const branchRows=rows.length?rows.map(g=>`<tr><td><b>${esc(g.branch)}</b></td><td>${g.ranges}</td><td>${g.received.toLocaleString()}</td><td>${g.issued.toLocaleString()}</td><td>${g.onHand.toLocaleString()}</td><td>${g.expected.toLocaleString()}</td><td>${vcell(g.variance)}</td></tr>`).join('')+`<tr class="tot-row"><td><b>All in scope</b></td><td>${tot.ranges}</td><td>${tot.received.toLocaleString()}</td><td>${tot.issued.toLocaleString()}</td><td>${tot.onHand.toLocaleString()}</td><td>${tot.expected.toLocaleString()}</td><td>${vcell(tot.variance)}</td></tr>`:'<tr><td colspan="7" class="empty">No stock ranges registered in scope.</td></tr>';const cover=stockCover();const coverRows=cover.length?cover.map(c=>`<tr><td><b>${esc(c.branch)}</b></td><td>${c.onHand.toLocaleString()}</td><td>${c.perMonth?c.perMonth.toLocaleString():'—'}</td><td>${c.months==null?'—':(c.months===Infinity?'∞':c.months.toFixed(1))}</td><td>${c.flag}</td></tr>`).join(''):'<tr><td colspan="5" class="empty">No stock in scope.</td></tr>';const inv=(data.inventory||[]).filter(allowed);const rangeRows=inv.length?inv.map(r=>{const t=num(r[4]),rem=num(r[5]);return `<tr><td><b>${esc(r[0])}</b></td><td>${esc(r[1])}</td><td>${esc(r[2])}</td><td>${esc(r[3])}</td><td>${t.toLocaleString()}</td><td>${(t-rem).toLocaleString()}</td><td>${rem.toLocaleString()}</td><td>${badge(r[6])}</td></tr>`}).join(''):'<tr><td colspan="8" class="empty">No ranges.</td></tr>';return `${kpis}<section class="card wide-card"><div class="card-head"><div><h3>Serial-stock reconciliation</h3><small>Per branch: leaves received into the vault vs recorded issuances vs book stock on hand. A non-zero variance means leaves are unaccounted for and must be investigated.</small></div><button class="ghost" onclick="reconExport()">Export CSV</button></div><div class="table-wrap"><table><thead><tr><th>Branch</th><th>Ranges</th><th>Received</th><th>Issued</th><th>On hand</th><th>Expected</th><th>Variance</th></tr></thead><tbody>${branchRows}</tbody></table></div></section><section class="card wide-card" style="margin-top:18px"><div class="card-head"><div><h3>Stock cover &amp; replenishment</h3><small>Months of cover = leaves on hand ÷ average monthly consumption (last 90 days). Reorder before cover runs out.</small></div></div><div class="table-wrap"><table><thead><tr><th>Branch</th><th>On hand</th><th>Avg / month</th><th>Months cover</th><th>Action</th></tr></thead><tbody>${coverRows}</tbody></table></div></section><section class="card wide-card" style="margin-top:18px"><div class="card-head"><div><h3>Registered serial ranges</h3><small>Every stock range with leaves consumed and remaining</small></div></div><div class="table-wrap"><table><thead><tr><th>Range ref</th><th>Branch</th><th>Type</th><th>Serial range</th><th>Total</th><th>Consumed</th><th>Remaining</th><th>Status</th></tr></thead><tbody>${rangeRows}</tbody></table></div></section>`}

// ---- Turnaround time ----
function tatData(){const idx={};(data.requests||[]).forEach(r=>idx[r[0]]=r);const out=[];(data.issuance||[]).filter(allowed).forEach(is=>{const rq=idx[is[1]];if(!rq)return;const rd=repParseDate(rq[6]),id=repParseDate(is[6]);if(!rd||!id)return;const days=Math.round((id.getTime()-rd.getTime())/86400000);if(days<0||days>7300)return;out.push({ref:rq[0],branch:is[3],days})});return out}
function tatBucket(d){if(d<=1)return '0–1 day';if(d<=3)return '2–3 days';if(d<=7)return '4–7 days';if(d<=14)return '8–14 days';return '>14 days'}
function tatExport(){exportCsv('turnaround-time',['Reference','Branch','Days'],tatData().map(i=>[i.ref,i.branch,i.days]))}
function reportTat(){const items=tatData();const n=items.length;const arr=items.map(i=>i.days).sort((a,b)=>a-b);const avg=n?Math.round(arr.reduce((a,b)=>a+b,0)/n):0;const median=n?arr[Math.floor(n/2)]:0;const worst=n?arr[n-1]:0;const kpis=`<div class="grid kpis">${repKpi('Completed (req→issue)',n.toLocaleString(),'','✓','Matched issuances')}${repKpi('Average TAT',n?avg+'d':'—','gold','◷','Request to issuance')}${repKpi('Median TAT',n?median+'d':'—','','▤')}${repKpi('Longest TAT',n?worst+'d':'—','red','↧')}</div>`;const order=['0–1 day','2–3 days','4–7 days','8–14 days','>14 days'];const rag=['green','green','amber','orange','red'];const counts={};items.forEach(i=>{const b=tatBucket(i.days);counts[b]=(counts[b]||0)+1});const maxC=Math.max(1,...order.map(o=>counts[o]||0));const chart=`<div class="rep-chart">${order.map((o,idx)=>{const c=counts[o]||0;return `<div class="rep-bar-row"><span class="rep-bar-label">${o}</span><div class="rep-bar-track"><div class="rep-bar-fill rag-${rag[idx]}" style="width:${Math.round(c/maxC*100)}%"></div></div><span class="rep-bar-val">${c} · ${n?Math.round(c/n*100):0}%</span></div>`}).join('')}</div>`;const by={};items.forEach(i=>{const g=by[i.branch]||(by[i.branch]={s:0,n:0,mx:0});g.s+=i.days;g.n++;g.mx=Math.max(g.mx,i.days)});const brRows=Object.keys(by).sort().map(b=>`<tr><td><b>${esc(b)}</b></td><td>${by[b].n}</td><td>${Math.round(by[b].s/by[b].n)}d</td><td>${by[b].mx}d</td></tr>`).join('')||'<tr><td colspan="4" class="empty">No completed issuances in scope.</td></tr>';return `${kpis}<section class="card wide-card"><div class="card-head"><div><h3>Turnaround time — request to issuance</h3><small>Elapsed days from a cheque-book request being raised to the book being issued. Only completed items are measured.</small></div><button class="ghost" onclick="tatExport()">Export CSV</button></div><div class="card-head" style="margin-top:2px"><div><h4 style="margin:0;font-size:13px">Distribution — ${n.toLocaleString()} completed</h4></div></div>${chart}</section><section class="card wide-card" style="margin-top:18px"><div class="card-head"><div><h3>By branch</h3><small>Average and longest turnaround per branch</small></div></div><div class="table-wrap"><table><thead><tr><th>Branch</th><th>Completed</th><th>Avg TAT</th><th>Longest</th></tr></thead><tbody>${brRows}</tbody></table></div></section>`}

// ---- Branch returns (period) ----
function retFilter(){return state.retFilter||(state.retFilter={from:monthStart(),to:todayISO()})}
function retSet(k,v){state.retFilter={...retFilter(),[k]:v};render()}
function inPeriod(dstr,f){const d=repParseDate(dstr);if(!d)return false;if(f.from&&d<new Date(f.from))return false;if(f.to){const b=new Date(f.to);b.setHours(23,59,59,999);if(d>b)return false}return true}
function returnsRows(){const f=retFilter();const by={};scopeBranches().forEach(b=>by[b]={branch:b,requests:0,issued:0,notified:0,destroyed:0});const ens=b=>by[b]||(by[b]={branch:b,requests:0,issued:0,notified:0,destroyed:0});(data.requests||[]).filter(allowed).forEach(r=>{if(inPeriod(r[6],f))ens(r[3]).requests++});(data.issuance||[]).filter(allowed).forEach(r=>{if(inPeriod(r[6],f))ens(r[3]).issued++});(data.notifications||[]).filter(allowed).forEach(r=>{if(inPeriod(r[7],f))ens(r[3]).notified++});(data.destructions||[]).filter(allowed).forEach(r=>{if(inPeriod(r[9],f))ens(r[4]).destroyed++});return Object.values(by).sort((a,b)=>a.branch.localeCompare(b.branch))}
function returnsExport(){exportCsv('branch-returns',['Branch','Requests','Issued','Notifications','Destroyed'],returnsRows().map(g=>[g.branch,g.requests,g.issued,g.notified,g.destroyed]))}
function reportReturns(){const f=retFilter();const rows=returnsRows();const tot=rows.reduce((a,g)=>({requests:a.requests+g.requests,issued:a.issued+g.issued,notified:a.notified+g.notified,destroyed:a.destroyed+g.destroyed}),{requests:0,issued:0,notified:0,destroyed:0});const body=rows.length?rows.map(g=>`<tr><td><b>${esc(g.branch)}</b></td><td>${g.requests}</td><td>${g.issued}</td><td>${g.notified}</td><td>${g.destroyed}</td></tr>`).join('')+`<tr class="tot-row"><td><b>Total</b></td><td>${tot.requests}</td><td>${tot.issued}</td><td>${tot.notified}</td><td>${tot.destroyed}</td></tr>`:'<tr><td colspan="5" class="empty">No branches in scope.</td></tr>';return `<section class="card wide-card"><div class="card-head"><div><h3>Branch returns</h3><small>Activity by branch for the selected period — use for daily or monthly returns.</small></div><span style="display:inline-flex;gap:8px"><button class="ghost" onclick="printReturns()">🖨 Print</button><button class="ghost" onclick="returnsExport()">Export CSV</button></span></div><div class="rep-filters"><label>From <input type="date" value="${esc(f.from||'')}" onchange="retSet('from',this.value)"></label><label>To <input type="date" value="${esc(f.to||'')}" onchange="retSet('to',this.value)"></label><button class="ghost xs" onclick="state.retFilter={from:monthStart(),to:todayISO()};render()">This month</button></div><div class="table-wrap" style="margin-top:8px"><table><thead><tr><th>Branch</th><th>Requests received</th><th>Books issued</th><th>Notifications</th><th>Destroyed</th></tr></thead><tbody>${body}</tbody></table></div></section>`}

// ---- Control exceptions ----
function reportExceptions(){const waivers=(data.adminAudit||[]).filter(a=>/waiv|directly/i.test(String(a[2]||'')));const rejects=(data.audit||[]).filter(allowed).filter(a=>/reject/i.test(String(a[1]||'')));const dir=data.directory||{};const sod=[];Object.entries(dir).forEach(([id,u])=>{const v=sodViolation(effPermsClient(u.role,u.groups));if(v)sod.push([u.name,id,u.role,`${permLabel(v[0])} ⨂ ${permLabel(v[1])}`])});const fourEyes=state.adminDirect?'OFF':'ON';const kpis=`<div class="grid kpis">${repKpi('Four-eyes waivers',waivers.length.toLocaleString(),waivers.length?'red':'green','⚠','Applied without 2nd admin')}${repKpi('SoD conflicts',sod.length.toLocaleString(),sod.length?'red':'green','⨂','Users with toxic combos')}${repKpi('Rejected transactions',rejects.length.toLocaleString(),'gold','↩','Maker-checker rejections')}${repKpi('Four-eyes status',fourEyes,fourEyes==='ON'?'green':'red','◉','Second-admin control')}</div>`;const wRows=waivers.length?waivers.map(a=>`<tr><td>${esc(a[0])}</td><td>${esc(a[1])}</td><td>${esc(a[2])}</td><td>${esc(a[3]||'—')}</td><td style="white-space:normal">${esc(a[4]||'')}</td></tr>`).join(''):'<tr><td colspan="5" class="empty">No four-eyes waivers on record.</td></tr>';const sRows=sod.length?sod.map(r=>`<tr><td><b>${esc(r[0])}</b></td><td>${esc(r[1])}</td><td>${esc(r[2])}</td><td><span class="badge stopped">${esc(r[3])}</span></td></tr>`).join(''):'<tr><td colspan="4" class="empty">No segregation-of-duties conflicts.</td></tr>';const rRows=rejects.length?rejects.map(a=>`<tr><td>${esc(a[0])}</td><td>${esc(a[1])}</td><td>${esc(a[2])}</td><td>${esc(a[3])}</td><td>${esc(a[5])}</td><td style="white-space:normal">${esc(a[6]||'')}</td></tr>`).join(''):'<tr><td colspan="6" class="empty">No rejected transactions in scope.</td></tr>';return `${kpis}<section class="card wide-card"><div class="card-head"><div><h3>Four-eyes waivers</h3><small>Administrative changes applied without a second administrator (four-eyes is currently ${fourEyes}). Restore four-eyes before go-live to eliminate these.</small></div></div><div class="table-wrap"><table><thead><tr><th>When</th><th>Actor</th><th>Action</th><th>Target</th><th>Detail</th></tr></thead><tbody>${wRows}</tbody></table></div></section><section class="card wide-card" style="margin-top:18px"><div class="card-head"><div><h3>Segregation-of-duties conflicts</h3><small>Users whose effective permissions include a prohibited combination</small></div></div><div class="table-wrap"><table><thead><tr><th>User</th><th>Staff ID</th><th>Role</th><th>Conflict</th></tr></thead><tbody>${sRows}</tbody></table></div></section><section class="card wide-card" style="margin-top:18px"><div class="card-head"><div><h3>Rejected transactions</h3><small>Maker-checker rejections in your scope</small></div></div><div class="table-wrap"><table><thead><tr><th>When</th><th>Action</th><th>Reference</th><th>Maker</th><th>Role</th><th>Remarks</th></tr></thead><tbody>${rRows}</tbody></table></div></section>`}

// ---- Destruction register + certificate ----
function destroyBook(ref){state.modal={type:'destroy',ctx:ref};state.openMenu=null;render()}
async function submitDestroy(){const ref=state.modal.ctx;const witness=((document.getElementById('destroy-witness')||{}).value||'').trim();const method=(document.getElementById('destroy-method')||{}).value||'Shredded';try{const r=await fetch('/api/aging/destroy',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({ref,witness,method})});const j=await r.json().catch(()=>({}));if(!r.ok)throw new Error(j.error||'Destruction failed.');applyState(j);state.modal=null;toast('Cheque book destroyed; certificate recorded.');render()}catch(e){toast(e.message||'Destruction failed.');render()}}
function printCert(cert){state.modal={type:'cert',ctx:cert};render()}
function doPrintCert(){document.body.classList.add('print-cert');window.print();setTimeout(()=>document.body.classList.remove('print-cert'),300)}
function destructionExport(){exportCsv('destruction-register',['Cert No','Request','Account','Customer','Branch','Book','Serials','Destroyed by','Witness','Date','Method'],(data.destructions||[]).filter(allowed).map(r=>r.slice(0,11)))}
function reportDestruction(){const rows=(data.destructions||[]).filter(allowed);const thisYear=rows.filter(r=>{const d=repParseDate(r[9]);return d&&d.getFullYear()===new Date().getFullYear()}).length;const kpis=`<div class="grid kpis" style="grid-template-columns:repeat(2,1fr);max-width:540px">${repKpi('Books destroyed',rows.length.toLocaleString(),'','🗑','On record')}${repKpi('This year',thisYear.toLocaleString(),'gold','▤','Current year')}</div>`;const body=rows.length?rows.map(r=>`<tr><td><b>${esc(r[0])}</b></td><td>${esc(r[1])}</td><td>${esc(r[3])}</td><td>${esc(r[4])}</td><td>${esc(r[6])}</td><td>${esc(r[7])}</td><td>${esc(r[8])}</td><td>${esc(r[9])}</td><td><button class="ghost xs" onclick="printCert('${esc(r[0])}')">Certificate</button></td></tr>`).join(''):'<tr><td colspan="9" class="empty">No destruction records yet. Destroy uncollected books from Reports ▸ Aging &amp; SLA.</td></tr>';return `${kpis}<section class="card wide-card"><div class="card-head"><div><h3>Cheque-book destruction register</h3><small>Immutable record of destroyed uncollected books, with authorising officer, witness and serial range. Print a certificate for each disposal.</small></div><button class="ghost" onclick="destructionExport()">Export CSV</button></div><div class="table-wrap"><table><thead><tr><th>Cert no.</th><th>Request</th><th>Customer</th><th>Branch</th><th>Serials</th><th>Destroyed by</th><th>Witness</th><th>Date</th><th></th></tr></thead><tbody>${body}</tbody></table></div></section>`}

// ---- Dashboard drill-down ----
function dashDetail(kind){state.modal={type:'dashdetail',kind};render()}
function recentReqTable(records){const H=['Reference','Account','Customer','Branch','Book','Status','Created'];const vis=(records||[]).filter(allowed);const head=`<thead><tr>${H.map(h=>`<th>${h}</th>`).join('')}</tr></thead>`;if(!vis.length)return `<div class="table-wrap"><table>${head}<tbody><tr><td colspan="7" class="empty">No records are available within your branch scope.</td></tr></tbody></table></div>`;const body=vis.slice(0,8).map(r=>`<tr class="rowlink" onclick="dashReqDetail('${esc(r[0])}')">${r.map((c,j)=>`<td>${H[j]==='Status'?badge(c):esc(c)}</td>`).join('')}</tr>`).join('');return `<div class="table-wrap"><table>${head}<tbody>${body}</tbody></table></div>`}
function dashReqDetail(ref){const row=(data.requests||[]).find(r=>r[0]===ref);if(!row)return;state.modal={type:'detail',headers:['Reference','Account','Customer','Branch','Book','Status','Created'],row};render()}
function dashDetailModal(kind){const A=r=>(r||[]).filter(allowed);let title,head,rows;if(kind==='issued'){title='Cheque books issued';head=['Reference','Request','Account','Branch','Serial range','Status','Date'];rows=A(data.issuance)}else if(kind==='leaves'){title='Leaves available';head=['Range','Branch','Type','Serial range','Total','Remaining','Status'];rows=A(data.inventory)}else if(kind==='vault'){title='Books in branch vault';head=['Batch','Branch','Customer','Book','Serial range'];rows=(data.printBatches||[]).filter(b=>(state.global||b.branch===state.branch)&&b.status==='In Branch Vault').flatMap(b=>(b.items||[]).map(it=>[b.id,b.branch,it.customer,it.size,`${it.serialStart} – ${it.serialEnd}`]))}else if(kind==='pending'){title='Awaiting authorisation';head=['Ref','Type','Item','Subject','Branch','Maker','When'];rows=A(data.approvals)}else if(kind==='progressed'){title='Requisitions progressed';head=['Reference','Account','Customer','Branch','Book','Status','Created'];rows=A(data.requests).filter(r=>!/pending|reject/i.test(r[5]))}else if(kind==='destruction'){title='Due for destruction';head=['Reference','Account','Customer','Branch','Book','Age'];rows=agingItems().filter(i=>i.age>=AGING_LIMIT_DAYS&&i.kind==='Uncollected book').map(i=>[i.ref,i.account,i.customer,i.branch,i.book,ageLabel(i.age)])}else{title='Cheque requisitions';head=['Reference','Account','Customer','Branch','Book','Status','Created'];rows=A(data.requests)}const bodyRows=rows.length?rows.slice(0,100).map(r=>`<tr>${r.map((c,j)=>`<td>${head[j]==='Status'?badge(c):esc(c)}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${head.length}" class="empty">Nothing to show in your scope.</td></tr>`;return `<div class="modal-backdrop" onclick="if(event.target===this){state.modal=null;render()}"><div class="modal wide-modal"><div class="card-head"><div><h2>${esc(title)}</h2><small class="muted-sm">${rows.length} record${rows.length===1?'':'s'} in your scope${rows.length>100?' · showing first 100':''}</small></div></div><div class="table-wrap" style="max-height:60vh"><table><thead><tr>${head.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${bodyRows}</tbody></table></div><div class="modal-actions"><button class="primary" onclick="state.modal=null;render()">Close</button></div></div></div>`}

function reportAudit(){const rows=(data.audit||[]).filter(allowed);return `<div class="module-toolbar"><div class="filters"><input class="search" placeholder="Filter audit trail" oninput="filterTable(this.value)"><span class="module-summary">${rows.length} audit event${rows.length===1?'':'s'} in scope</span></div><button class="ghost" onclick="exportCsv('audit-trail',['When','Action','Reference','Maker','Role','Branch','Remarks'],(data.audit||[]).filter(allowed))">Export CSV</button></div><section class="card wide-card"><div class="card-head"><div><h3>Business audit trail</h3><small>Immutable record of cheque operations and authorisations</small></div></div>${table(['When','Action','Reference','Maker','Role','Branch','Remarks'],data.audit||[])}</section>`}
function reportSystem(){const rows=state.systemLog||[];const f=state.logFilter||{};const body=rows.length?rows.map(r=>`<tr><td>${esc(r.ts)}</td><td>${badge(r.level)}</td><td>${esc(r.event)}</td><td>${esc(r.actor||'—')}</td><td>${esc(r.ip||'—')}</td><td>${esc(r.detail||'')}</td></tr>`).join(''):'<tr><td colspan="6" class="empty">No log entries for this filter.</td></tr>';return `<div class="module-toolbar"><div class="filters"><select onchange="state.logFilter={...state.logFilter,level:this.value};loadSystemLog()"><option value="">All levels</option>${['SECURITY','WARN','ERROR','INFO'].map(l=>`<option ${f.level===l?'selected':''}>${l}</option>`).join('')}</select><input class="search" placeholder="Search event / actor / detail, Enter to apply" value="${esc(f.q||'')}" onkeydown="if(event.key==='Enter'){state.logFilter={...state.logFilter,q:this.value};loadSystemLog()}"><span class="module-summary">${rows.length} entr${rows.length===1?'y':'ies'} (max 500)</span></div><button class="ghost" onclick="exportCsv('system-log',['Time','Level','Event','Actor','IP','Detail'],(state.systemLog||[]).map(r=>[r.ts,r.level,r.event,r.actor,r.ip,r.detail]))">Export CSV</button></div><div class="notice">Security &amp; system events (sign-ins, failures, lockouts, admin changes, imports, errors) with source IP. Append-only; apply a retention policy in production.</div><section class="card wide-card"><div class="table-wrap"><table><thead><tr><th>Time (UTC)</th><th>Level</th><th>Event</th><th>Actor</th><th>IP</th><th>Detail</th></tr></thead><tbody>${body}</tbody></table></div></section>`}
function reportAccess(){const dir=data.directory||{},groups=data.groups||{},roles=data.roles||{};const groupRows=Object.entries(groups).map(([name,g])=>{const perms=new Set((g.roles||[]).flatMap(r=>roles[r]?.permissions||[]));const members=Object.values(dir).filter(u=>(u.groups||[]).includes(name)).length;return [name,g.branch||'All Branches',(g.roles||[]).join(', ')||'—',[...perms].join(', ')||'—',String(members)]});const userRows=Object.entries(dir).map(([id,u])=>{const set=effPermsClient(u.role,u.groups);const v=sodViolation(set);return [u.name,id,u.role,(u.groups||[]).join(', ')||'—',String(set.size),u.status,u.lastReviewed||'—',v?`SoD: ${v[0]} vs ${v[1]}`:'—']});const gtable=`<table><thead><tr><th>Group</th><th>Branch</th><th>Roles</th><th>Permissions granted</th><th>Members</th></tr></thead><tbody>${groupRows.map(r=>`<tr>${r.map(c=>`<td>${esc(c)}</td>`).join('')}</tr>`).join('')||'<tr><td colspan="5" class="empty">No groups.</td></tr>'}</tbody></table>`;const utable=`<table><thead><tr><th>User</th><th>Staff ID</th><th>Role</th><th>Groups</th><th>Perms</th><th>Status</th><th>Last reviewed</th><th>Access flag</th></tr></thead><tbody>${userRows.map(r=>`<tr>${r.map((c,i)=>`<td>${i===5?badge(c):esc(c)}</td>`).join('')}</tr>`).join('')}</tbody></table>`;return `<div class="module-toolbar"><span class="module-summary">${Object.keys(groups).length} groups · ${Object.keys(dir).length} users</span><button class="ghost" onclick="exportAccessCsv()">Export access CSV</button></div><section class="card wide-card"><div class="card-head"><div><h3>User groups</h3><small>Each group's roles, effective permissions and membership</small></div></div><div class="table-wrap">${gtable}</div></section><section class="card wide-card" style="margin-top:18px"><div class="card-head"><div><h3>User access review</h3><small>Effective access per user, with recertification date and segregation-of-duties flags</small></div></div><div class="table-wrap">${utable}</div></section>`}
function setAdminTab(t){state.adminTab=t;render()}
function admin(){if(!isAdmin())return shell(`<div class="denied"><b>Administration restricted</b><br>Only staff with administrative permissions can manage users, roles, groups and controls.</div>`,`Administration`,'SYSTEM GOVERNANCE');const tabs=[['users','Users'],['roles','Roles'],['groups','Groups'],['branches','Branches'],['sod','Segregation of Duties'],['approvals','Admin Approvals'],['sms','SMS Gateway'],...(has('customers.manage')?[['customers','Customer Database']]:[]),['audit','Change Audit']];const tab=state.adminTab||'users';const qn=(data.adminQueue||[]).length;const nav=`<div class="admin-tabs">${tabs.map(t=>`<button class="admin-tab ${tab===t[0]?'active':''}" onclick="setAdminTab('${t[0]}')">${t[1]}${t[0]==='approvals'&&qn?` <span class="tab-badge">${qn}</span>`:''}</button>`).join('')}</div>`;const views={users:adminUsersView,roles:adminRolesView,groups:adminGroupsView,branches:adminBranchesView,sod:adminSodView,approvals:adminApprovalsView,sms:adminSmsView,customers:adminCustomersView,audit:adminAuditView};const banner=state.adminDirect?`<div class="warn-banner">⚠ <b>Four-eyes authorisation is temporarily OFF</b> for System Administrators (setup / training mode). Administrative changes apply immediately without a second authoriser. Restore two-administrator authorisation before go-live.</div>`:'';return shell(banner+nav+(views[tab]||adminUsersView)(),'Administration','SYSTEM GOVERNANCE')}
const CUSTOMER_COLS=[['Account Number',1,'Unique key — one row per account, never duplicated.'],['First Name',0,'Personal given name.'],['Middle Name',0,'Personal middle name.'],['Surname',0,'Personal family name.'],['Company Name',0,'Name for corporate accounts (used when there is no personal name).'],['Mobile Phone Number',0,'Preferred number for customer SMS alerts.'],['Main Phone Number',0,'Used when Mobile is blank.'],['Mobile Money Number',0,'Used when Mobile and Main are blank.'],['Account Type',0,'e.g. Savings, Current.'],['Status Of Account',0,'e.g. Active, Dormant.'],['Account Branch',0,'Customer’s home branch.']];
function adminCustomersView(){const s=state.customerStats||{};const fmtRows=CUSTOMER_COLS.map(c=>`<tr><td><code class="col-name">${c[0]}</code></td><td>${c[1]?'<span class="badge pending">Required</span>':'<span class="badge draft">Optional</span>'}</td><td style="white-space:normal">${c[2]}</td></tr>`).join('');return `<section class="card" style="max-width:820px"><div class="card-head"><div><h3>Customer database</h3><small>The monthly customer extract. Uploads upsert by account number (new accounts added, existing refreshed); phone numbers may repeat.</small></div></div><div class="grid kpis" style="grid-template-columns:1fr 1fr;margin-bottom:16px"><div class="card kpi"><div><div class="kpi-label">Customers on file</div><strong>${(s.total||0).toLocaleString()}</strong><small>Unique account numbers</small></div><div class="metric-icon">⌸</div></div><div class="card kpi"><div><div class="kpi-label">Last import</div><strong style="font-size:16px">${esc(s.lastImport||'Never')}</strong><small>Most recent monthly update</small></div><div class="metric-icon gold">▤</div></div></div><div class="card" style="margin-bottom:16px;padding:0"><div class="card-head" style="padding:18px 18px 0"><div><h3>Expected upload format</h3><small>The first row of the CSV must contain these column headers, spelled exactly. Column order doesn’t matter and any extra columns are ignored.</small></div><button class="secondary" onclick="downloadCustomerTemplate()">⬇ Download CSV template</button></div><div class="table-wrap" style="padding:8px 18px 4px"><table><thead><tr><th>Column header</th><th>Required</th><th>Purpose</th></tr></thead><tbody>${fmtRows}</tbody></table></div><div class="notice" style="margin:6px 18px 18px">The customer <b>name</b> is built from First / Middle / Surname — or <b>Company Name</b> for corporate accounts. The <b>alert phone</b> is taken from Mobile → Main → Mobile Money (the first one present). Account numbers must be unique; phone numbers may repeat across accounts.</div></div><div class="notice">Export the monthly file from your banking application as <b>CSV</b> (Excel → Save As → CSV UTF-8), then upload it here. Large files are streamed and de-duplicated automatically.</div><div class="field"><label>Monthly customer CSV</label><input id="cust-file" type="file" accept=".csv,text/csv"></div><div class="form-actions"><button class="primary" id="cust-import-btn" onclick="importCustomers()">Upload &amp; update database</button></div></section>`}
function downloadCustomerTemplate(){const headers=CUSTOMER_COLS.map(c=>c[0]);const rows=[['1000123456','Ama','Serwaa','Owusu','','0244000111','0302000111','','Savings','Active','Nsawam'],['2000987654','','','','Adom Ventures Ltd','0209888777','','','Current','Active','Koforidua']];exportCsv('customer-import-template',headers,rows);}
async function importCustomers(){const inp=document.querySelector('#cust-file');const f=inp&&inp.files[0];if(!f){toast('Choose a CSV file first.');return}const btn=document.querySelector('#cust-import-btn');if(btn){btn.disabled=true;btn.textContent='Importing…'}try{const text=await f.text();const r=await fetch('/api/customers/import',{method:'POST',headers:{'Content-Type':'text/csv'},body:text});const j=await r.json().catch(()=>({}));if(!r.ok)throw new Error(j.error||'Import failed.');state.customerStats={total:j.total,lastImport:j.lastImport};toast(`Imported: ${(j.inserted||0).toLocaleString()} new, ${(j.updated||0).toLocaleString()} updated, ${(j.total||0).toLocaleString()} on file.`)}catch(e){toast(e.message||'Import failed.')}render()}
function adminSmsView(){const s=state.sms||{};const manage=has('admin.manage');return `<section class="card" style="max-width:580px"><div class="card-head"><div><h3>SMS gateway — Arkesel</h3><small>Customer alerts are delivered through this gateway when a branch receives an itemised cheque.</small></div>${s.enabled?'<span class="badge active">Enabled</span>':'<span class="badge disabled">Disabled</span>'}</div><div class="notice">Paste your Arkesel <b>API key</b> and your <b>registered Sender ID</b> below. The key is stored on the server and is never shown again in full.</div><div class="field"><label>Provider</label><input value="Arkesel" readonly></div><div class="field"><label>Sender ID (registered with Arkesel)</label><input id="sms-sender" value="${esc(s.senderId||'')}" placeholder="e.g. AkuapemCB" ${manage?'':'readonly'}></div><div class="field"><label>API key</label><input id="sms-key" type="password" placeholder="${s.configured?esc(s.apiKeyMasked)+' — leave blank to keep current':'Paste your Arkesel API key'}" ${manage?'':'readonly'}></div><label class="perm-cbl"><input type="checkbox" id="sms-enabled" ${s.enabled?'checked':''} ${manage?'':'disabled'}> Enable live SMS sending to customers</label>${manage?`<div class="form-actions"><button class="primary" onclick="saveSmsSettings()">Save settings</button></div><div style="border-top:1px solid var(--line);margin-top:16px;padding-top:14px"><b style="font-size:13px">Send a test message</b><div class="sod-add" style="margin-top:10px"><input id="sms-test" placeholder="Phone e.g. 0244000000"><button class="ghost" onclick="testSms()">Send test SMS</button></div></div>`:''}</section>`}
async function saveSmsSettings(){const senderId=val('#sms-sender');const apiKey=document.querySelector('#sms-key').value;const enabled=document.querySelector('#sms-enabled').checked;try{const r=await fetch('/api/admin/sms/save',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({senderId,apiKey,enabled})});const j=await r.json().catch(()=>({}));if(!r.ok)throw new Error(j.error||'Unable to save.');applyState(j);toast('SMS gateway settings saved.')}catch(e){toast(e.message||'Unable to save.')}render()}
async function testSms(){const phone=val('#sms-test');if(!phone){toast('Enter a phone number.');return}try{const r=await fetch('/api/admin/sms/test',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({phone})});const j=await r.json().catch(()=>({}));applyState(j);const t=j.smsTest||{};toast(t.ok?'Test SMS accepted by gateway.':`Test failed: ${t.detail||j.error||'error'}`)}catch(e){toast(e.message||'Test failed.')}render()}
function adminUsersView(){const manage=has('admin.manage');const rows=Object.entries(data.directory||{}).map(([id,u])=>{const v=sodViolation(effPermsClient(u.role,u.groups));const groups=(u.groups||[]).map(g=>`<span class="chip">${esc(g)}</span>`).join(' ')||'<span class="muted-sm">—</span>';return `<tr><td><b>${esc(u.name)}</b><br><span class="muted-sm">${esc(id)}</span></td><td>${esc(u.role)}${v?` <span class="sod-flag" title="SoD conflict: ${esc(v[0])} vs ${esc(v[1])}">⚠ SoD</span>`:''}</td><td>${groups}</td><td>${esc(u.branch)}</td><td>${u.phone?esc(u.phone):'<span class="warn-sm">— none —</span>'}</td><td>${badge(u.status)}</td><td>${esc(u.lastReviewed||'—')}</td><td class="admin-actions">${manage?`<div class="rowmenu"><button class="ghost xs" onclick="toggleMenu('${esc(id)}')">Actions ▾</button>${state.openMenu===id?`<div class="rowmenu-pop"><button onclick="openAdmin('user-role','${esc(id)}')">Role</button><button onclick="openAdmin('user-groups','${esc(id)}')">Groups</button><button onclick="openAdmin('user-phone','${esc(id)}')">Phone</button><button onclick="openAdmin('user-resetpw','${esc(id)}')">Reset PW</button><button onclick="adminRecertify('${esc(id)}')">Recertify</button>${u.status==='Active'?`<button class="danger" onclick="adminDisable('${esc(id)}')">Disable</button>`:`<button onclick="adminEnable('${esc(id)}')">Enable</button>`}</div>`:''}</div>`:'<span class="muted-sm">View only</span>'}</td></tr>`}).join('');return `<div class="module-toolbar"><span class="module-summary">${Object.keys(data.directory||{}).length} users · ${state.adminDirect?'changes apply immediately (four-eyes off)':'privilege grants require a second administrator'}</span>${manage?`<span style="display:inline-flex;gap:10px"><button class="ghost" onclick="openAdmin('import-users')">⬆ Import users</button><button class="primary" onclick="openAdmin('add-user')">＋ Add user</button></span>`:''}</div><section class="card wide-card"><div class="table-wrap"><table><thead><tr><th>User</th><th>Role</th><th>Groups</th><th>Branch</th><th>Reset phone</th><th>Status</th><th>Last reviewed</th><th></th></tr></thead><tbody>${rows}</tbody></table></div></section>`}
function adminRolesView(){const manage=has('admin.manage');const rows=Object.entries(data.roles||{}).map(([name,r])=>`<tr><td><b>${esc(r.label||name)}</b>${r.system?' <span class="chip sys">built-in</span>':''}</td><td>${r.global?'Global (all branches)':'Branch-scoped'}</td><td>${(r.permissions||[]).map(p=>`<span class="chip">${esc(permLabel(p))}</span>`).join(' ')||'<span class="muted-sm">none</span>'}</td><td class="admin-actions">${manage?`<button class="ghost xs" onclick="openAdmin('role-edit','${esc(name)}')">Edit</button>${r.system?'':`<button class="ghost xs danger" onclick="adminDeleteRole('${esc(name)}')">Delete</button>`}`:''}</td></tr>`).join('');return `<div class="module-toolbar"><span class="module-summary">Roles are permission bundles. Changes are routed for a second administrator's authorisation.</span>${manage?`<button class="primary" onclick="openAdmin('role-edit')">＋ New role</button>`:''}</div><section class="card wide-card"><div class="table-wrap"><table><thead><tr><th>Role</th><th>Scope</th><th>Permissions</th><th></th></tr></thead><tbody>${rows}</tbody></table></div></section>`}
function adminGroupsView(){const manage=has('admin.manage');const members=g=>Object.values(data.directory||{}).filter(u=>(u.groups||[]).includes(g)).length;const rows=Object.entries(data.groups||{}).map(([name,g])=>`<tr><td><b>${esc(name)}</b><br><span class="muted-sm">${esc(g.description||'')}</span></td><td>${esc(g.branch||'All Branches')}</td><td>${(g.roles||[]).map(r=>`<span class="chip">${esc(r)}</span>`).join(' ')||'<span class="muted-sm">none</span>'}</td><td>${members(name)}</td><td class="admin-actions">${manage?`<button class="ghost xs" onclick="openAdmin('group-edit','${esc(name)}')">Edit</button><button class="ghost xs danger" onclick="adminDeleteGroup('${esc(name)}')">Delete</button>`:''}</td></tr>`).join('');return `<div class="module-toolbar"><span class="module-summary">Groups collect users and grant them roles.</span>${manage?`<button class="primary" onclick="openAdmin('group-edit')">＋ New group</button>`:''}</div><section class="card wide-card"><div class="table-wrap"><table><thead><tr><th>Group</th><th>Branch</th><th>Roles</th><th>Members</th><th></th></tr></thead><tbody>${rows}</tbody></table></div></section>`}
function adminSodView(){const manage=has('admin.manage');const cat=state.permCatalog||[];const pairs=(data.sodMatrix||[]).map((p,i)=>`<div class="sod-pair"><span>${esc(permLabel(p[0]))} <b>⨂</b> ${esc(permLabel(p[1]))}</span>${manage?`<button class="ghost xs danger" onclick="adminRemoveSod('${esc(p[0])}','${esc(p[1])}')">Remove</button>`:''}</div>`).join('')||'<p class="muted-sm">No rules defined.</p>';const opts=cat.map(p=>`<option value="${esc(p.id)}">${esc(p.label)}</option>`).join('');const viol=[];for(const [id,u] of Object.entries(data.directory||{})){const v=sodViolation(effPermsClient(u.role,u.groups));if(v)viol.push(`<tr><td>${esc(u.name)}</td><td>${esc(id)}</td><td>${esc(permLabel(v[0]))} ⨂ ${esc(permLabel(v[1]))}</td></tr>`)}const violTable=viol.length?`<div class="table-wrap"><table><thead><tr><th>User</th><th>Staff ID</th><th>Conflict</th></tr></thead><tbody>${viol.join('')}</tbody></table></div>`:'<p class="ok-note">✓ No users currently hold a conflicting pair of permissions.</p>';return `<div class="grid" style="grid-template-columns:1fr 1fr;gap:18px"><section class="card"><div class="card-head"><div><h3>Mutually-exclusive permissions</h3><small>Static separation of duties — blocked at assignment</small></div></div>${pairs}${manage?`<div class="sod-add"><select id="sod-a">${opts}</select><span>⨂</span><select id="sod-b">${opts}</select><button class="primary" onclick="adminAddSod()">Add rule</button></div>`:''}</section><section class="card"><div class="card-head"><div><h3>Violations report</h3><small>Users holding a conflicting pair right now</small></div></div>${violTable}</section></div>`}
function adminBranchesView(){const manage=has('admin.manage');const rows=branches.map(b=>`<tr><td><b>${esc(b)}</b></td><td>${badge('Active')}</td></tr>`).join('')||'<tr><td colspan="2" class="muted-sm">No branches defined.</td></tr>';const pending=(data.adminQueue||[]).filter(c=>c.type==='branch/create');const pend=pending.length?`<div class="notice">${pending.length} new branch${pending.length>1?'es':''} awaiting a second administrator in <b>Admin Approvals</b>: ${pending.map(c=>esc((c.payload&&c.payload.name)||'')).join(', ')}.</div>`:'';return `<div class="module-toolbar"><span class="module-summary">${branches.length} branch${branches.length===1?'':'es'} · used across all branch selectors, scoping and reports</span>${manage?`<button class="primary" onclick="openAdmin('add-branch')">＋ Add branch</button>`:'<span class="muted-sm">View only</span>'}</div>${pend}<section class="card wide-card"><div class="table-wrap"><table><thead><tr><th>Branch</th><th>Status</th></tr></thead><tbody>${rows}</tbody></table></div></section>`}
function submitBranch(){return adminPost('branch/create',{name:val('#ab-name')},'Branch submitted for authorisation.')}
function adminApprovalsView(){const canAuth=has('admin.authorise');const q=data.adminQueue||[];const rows=q.map(c=>{const own=c.submittedBy===state.user;return `<div class="vault-item"><div class="vault-item-info"><b>${esc(c.summary)}</b><span>Submitted by ${esc(c.submittedBy)} · ${esc(c.submittedAt)}</span></div><div class="vault-actions">${!canAuth?'<span class="muted-sm">Awaiting an authoriser</span>':(own&&!state.adminDirect)?'<span class="vault-note">You submitted this — another administrator must authorise.</span>':`<button class="ghost xs danger" onclick="adminRejectChange('${esc(c.id)}')">Reject</button><button class="primary xs" onclick="adminAuthChange('${esc(c.id)}')">Authorise ✓</button>`}</div></div>`}).join('');return `<section class="card"><div class="card-head"><div><h3>Pending administrative changes</h3><small>Every privilege grant needs a second administrator (four-eyes)</small></div></div>${q.length?rows:'<p class="ok-note">✓ Nothing awaiting authorisation.</p>'}</section>`}
function adminAuditView(){return `<section class="card wide-card"><div class="card-head"><div><h3>Administrative change audit</h3><small>Immutable record of every governance action</small></div></div><div class="table-wrap"><table><thead><tr><th>When</th><th>Actor</th><th>Action</th><th>Target</th><th>Detail</th></tr></thead><tbody>${(data.adminAudit||[]).map(a=>`<tr>${a.map(c=>`<td>${esc(c)}</td>`).join('')}</tr>`).join('')||'<tr><td colspan="5" class="empty">No entries.</td></tr>'}</tbody></table></div></section>`}
function openAdmin(kind,ctx){state.modal={type:'admin',kind,ctx:ctx||null};state.openMenu=null;render()}
async function adminPost(path,body,okMsg){try{const r=await fetch('/api/admin/'+path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body||{})});const j=await r.json().catch(()=>({}));if(!r.ok)throw new Error(j.error||'Action failed.');applyState(j);if(j.tempPassword){state.modal={type:'admin',kind:'tempcreds',ctx:{user:j.tempUser,pw:j.tempPassword}};render();return}state.modal=null;toast(okMsg)}catch(e){toast(e.message||'Action failed.')}render()}
function openPw(){state.modal={type:'pw'};render()}
async function submitPassword(){const currentPassword=val('#pw-current'),newPassword=val('#pw-new'),confirm=val('#pw-confirm');if(newPassword!==confirm){toast('New passwords do not match.');return}try{const r=await fetch('/api/password',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({currentPassword,newPassword})});const j=await r.json().catch(()=>({}));if(!r.ok)throw new Error(j.error||'Unable to change password.');state.modal=null;toast('Password changed.')}catch(e){toast(e.message||'Unable to change password.')}render()}
function adminRecertify(id){confirmAction(`Recertify access for ${uName(id)}?`,()=>adminPost('user/recertify',{uid:id},'Access recertified.'))}
function adminDisable(id){confirmAction(`Disable ${uName(id)}? Their sessions end immediately.`,()=>adminPost('user/disable',{uid:id},'User disabled; sessions ended.'))}
function adminEnable(id){confirmAction(`Re-enable ${uName(id)}?`,()=>adminPost('user/enable',{uid:id},'User re-enabled.'))}
function adminDeleteRole(name){confirmAction(`Delete role "${name}"? This cannot be undone.`,()=>adminPost('role/delete',{name},'Role deleted.'))}
function adminDeleteGroup(name){confirmAction(`Delete group "${name}"?`,()=>adminPost('group/delete',{name},'Group deleted.'))}
function adminRemoveGroup(uid,g){confirmAction(`Remove ${uName(uid)} from group "${g}"?`,()=>adminPost('user/groups/remove',{uid,group:g},'Removed from group.'))}
function adminAddSod(){return adminPost('sod/add',{a:val('#sod-a'),b:val('#sod-b')},'SoD rule added.')}
function adminRemoveSod(a,b){confirmAction('Remove this segregation-of-duties rule?',()=>adminPost('sod/remove',{a,b},'SoD rule removed.'))}
function adminAuthChange(id){confirmAction('Authorise and apply this change?',()=>adminPost('change/authorise',{id},'Change authorised and applied.'))}
function adminRejectChange(id){confirmAction('Reject this change?',()=>adminPost('change/reject',{id},'Change rejected.'))}
function submitAddUser(){return adminPost('user/create',{id:val('#au-id'),name:val('#au-name'),phone:val('#au-phone'),branch:val('#au-branch'),role:val('#au-role')},'User creation submitted for authorisation.')}
function submitUserPhone(uid){return adminPost('user/phone',{uid,phone:val('#up-phone')},'Phone update submitted for authorisation.')}
async function submitUsersImport(){const inp=document.querySelector('#uimp-file');const f=inp&&inp.files[0];if(!f){toast('Choose a CSV file first.');return}const btn=document.querySelector('#uimp-btn');if(btn){btn.disabled=true;btn.textContent='Importing…'}try{const text=await f.text();const r=await fetch('/api/users/import',{method:'POST',headers:{'Content-Type':'text/csv'},body:text});const j=await r.json().catch(()=>({}));if(!r.ok)throw new Error(j.error||'Import failed.');applyState(j);state.lastImport=j.importResults||[];const im=j.imported||{};toast(`Imported: ${im.created||0} created, ${im.skipped||0} skipped, ${im.errors||0} error(s).`);state.modal={type:'admin',kind:'import-results',ctx:j.importResults||[]};render();return}catch(e){toast(e.message||'Import failed.')}render()}
function exportImportCreds(){const rows=(state.lastImport||[]).map(r=>[r.name,r.email,r.role,r.branch,r.status,r.tempPassword||'']);exportCsv('acb-user-credentials',['Name','Email','Role','Branch','Status','One-time password'],rows)}
function resetUserPw(uid,mode){confirmAction(mode==='otp'?'Send an SMS reset code to this user?':'Generate a one-time password for this user?',()=>doResetUserPw(uid,mode))}
async function doResetUserPw(uid,mode){try{const r=await fetch('/api/admin/user/resetpw',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({uid,mode})});const j=await r.json().catch(()=>({}));if(!r.ok)throw new Error(j.error||'Reset failed.');applyState(j);if(j.tempPassword){state.modal={type:'admin',kind:'tempcreds',ctx:{user:j.tempUser,pw:j.tempPassword}};render();return}state.modal=null;if(j.resetSms){toast(j.resetSms.ok?'Reset code sent to the user by SMS.':`SMS not sent: ${j.resetSms.detail}`)}else{toast('Password reset.')}render()}catch(e){toast(e.message||'Reset failed.');render()}}
function submitUserRole(uid){return adminPost('user/role',{uid,role:val('#ur-role')},'Role change submitted for authorisation.')}
function submitAddGroupMember(uid){return adminPost('user/groups/add',{uid,group:val('#ug-add')},'Group assignment submitted for authorisation.')}
function submitRole(){const permissions=[...document.querySelectorAll('.perm-cb:checked')].map(c=>c.value);return adminPost('role/save',{name:val('#role-name'),label:val('#role-label'),global:document.querySelector('#role-global').checked,permissions},'Role change submitted for authorisation.')}
function submitGroup(){const roles=[...document.querySelectorAll('.grole-cb:checked')].map(c=>c.value);return adminPost('group/save',{name:val('#group-name'),description:val('#group-desc'),branch:val('#group-branch'),roles},'Group change submitted for authorisation.')}
function adminModal(){const m=state.modal;const cat=state.permCatalog||[];const roleOpts=Object.keys(data.roles||{}).map(r=>`<option>${esc(r)}</option>`).join('');const branchOpts=['All Branches',...branches].map(b=>`<option>${esc(b)}</option>`).join('');function wrap(title,bodyHtml,actionBtn){return `<div class="modal-backdrop"><div class="modal admin-modal"><h2>${title}</h2>${bodyHtml}<div class="modal-actions"><button class="ghost" onclick="state.modal=null;render()">Cancel</button>${actionBtn}</div></div></div>`}
  if(m.kind==='add-user')return wrap('Add user',`<div class="form-grid"><div class="field"><label>Staff email</label><input id="au-id" placeholder="name@acb.com"></div><div class="field"><label>Full name</label><input id="au-name"></div><div class="field"><label>Mobile phone (for password reset)</label><input id="au-phone" placeholder="0244000000"></div><div class="field"><label>Role</label><select id="au-role">${roleOpts}</select></div><div class="field"><label>Branch</label><select id="au-branch">${branchOpts}</select></div></div><p class="muted-sm">A registered phone is required so the user can reset a forgotten password by SMS one-time code. Creation is queued for a second administrator; a one-time password is generated and shown once, to the authoriser, when the change is approved.</p>`,`<button class="primary" onclick="submitAddUser()">Submit for authorisation</button>`);
  if(m.kind==='user-phone'){const u=(data.directory||{})[m.ctx]||{};return wrap(`Reset phone — ${esc(u.name||m.ctx)}`,`<div class="field"><label>Mobile phone number</label><input id="up-phone" placeholder="0244000000" value="${esc(u.phone||'')}"></div><p class="muted-sm">This is the number that receives password-reset one-time codes. Changing it is queued for a second administrator.</p>`,`<button class="primary" onclick="submitUserPhone('${esc(m.ctx)}')">Submit</button>`)}
  if(m.kind==='user-resetpw'){const u=(data.directory||{})[m.ctx]||{};return wrap(`Reset password — ${esc(u.name||m.ctx)}`,`<p class="muted-sm">Choose how to reset this user's password. Both options are recorded in the audit trail and system log.</p><div class="reset-opts"><div class="reset-opt"><b>One-time password</b><p class="muted-sm">Generates a temporary password shown once to you; hand it to the user, who must change it at next sign-in.</p><button class="primary" onclick="resetUserPw('${esc(m.ctx)}','temp')">Generate one-time password</button></div><div class="reset-opt"><b>SMS reset code</b><p class="muted-sm">${u.phone?`Sends a 6-digit code to ${esc(u.phone)}; the user completes the reset on the Forgot-password screen.`:'No phone on file — add one first (via <b>Phone</b>) to use this option.'}</p><button class="primary" onclick="resetUserPw('${esc(m.ctx)}','otp')" ${u.phone?'':'disabled'}>Send SMS code</button></div></div>`,'')}
  if(m.kind==='import-users')return wrap('Import users (CSV)',`<div class="notice">Upload a <b>CSV</b> with columns <b>Full Name, Staff Email, Mobile Phone, Role, Branch</b> (the import template, saved as CSV). Existing emails are skipped. Each new user gets a one-time password shown once here — export and distribute it securely.</div><div class="field"><label>Users CSV</label><input id="uimp-file" type="file" accept=".csv,text/csv"></div>`,`<button class="primary" id="uimp-btn" onclick="submitUsersImport()">Upload &amp; create users</button>`);
  if(m.kind==='import-results'){const rows=(m.ctx||[]).map(r=>`<tr><td>${esc(r.name||'')}</td><td>${esc(r.email||'')}</td><td>${esc(r.role||'')}</td><td>${esc(r.branch||'')}</td><td>${r.status==='created'?'<span class="badge active">created</span>':r.status==='skipped'?'<span class="badge draft">skipped</span>':'<span class="badge rejected">error</span>'}${r.detail?` <span class="muted-sm">${esc(r.detail)}</span>`:''}</td><td>${r.tempPassword?`<code class="col-name">${esc(r.tempPassword)}</code>`:'—'}</td></tr>`).join('');return `<div class="modal-backdrop"><div class="modal modal-lg"><h2>Import results</h2><div class="notice">One-time passwords are shown <b>once</b>. Export them now and hand each to its owner securely; they must change it at first sign-in.</div><div class="table-wrap" style="max-height:340px;overflow:auto"><table><thead><tr><th>Name</th><th>Email</th><th>Role</th><th>Branch</th><th>Status</th><th>One-time password</th></tr></thead><tbody>${rows}</tbody></table></div><div class="modal-actions"><button class="secondary" onclick="exportImportCreds()">⬇ Export credentials CSV</button><button class="primary" onclick="state.modal=null;render()">Done</button></div></div></div>`}
  if(m.kind==='add-branch')return wrap('Add branch',`<div class="field"><label>Branch name</label><input id="ab-name" placeholder="e.g. Kumasi Branch"></div><p class="muted-sm">Use the full display name (e.g. “Kumasi Branch”). Adding a branch is queued for a second administrator; once authorised it appears in every branch selector across the system.</p>`,`<button class="primary" onclick="submitBranch()">Submit for authorisation</button>`);
  if(m.kind==='tempcreds')return wrap('One-time password',`<p>A temporary password has been generated for <b>${esc(m.ctx.user)}</b>. Share it securely — it is shown only once, and the user should change it after first sign-in.</p><div class="temp-cred">${esc(m.ctx.pw)}</div>`,'');
  if(m.kind==='user-role'){const u=(data.directory||{})[m.ctx]||{};return wrap(`Change role — ${esc(u.name||m.ctx)}`,`<div class="field"><label>New role</label><select id="ur-role">${Object.keys(data.roles||{}).map(r=>`<option ${r===u.role?'selected':''}>${esc(r)}</option>`).join('')}</select></div><p class="muted-sm">Blocked if it would breach segregation of duties; queued for a second administrator.</p>`,`<button class="primary" onclick="submitUserRole('${esc(m.ctx)}')">Submit</button>`)}
  if(m.kind==='user-groups'){const u=(data.directory||{})[m.ctx]||{};const cur=(u.groups||[]).map(g=>`<div class="vault-item"><span>${esc(g)}</span><button class="ghost xs danger" onclick="adminRemoveGroup('${esc(m.ctx)}','${esc(g)}')">Remove</button></div>`).join('')||'<p class="muted-sm">No groups assigned.</p>';const avail=Object.keys(data.groups||{}).filter(g=>!(u.groups||[]).includes(g));return wrap(`Groups — ${esc(u.name||m.ctx)}`,`${cur}<div class="sod-add">${avail.length?`<select id="ug-add">${avail.map(g=>`<option>${esc(g)}</option>`).join('')}</select><button class="primary" onclick="submitAddGroupMember('${esc(m.ctx)}')">Add (queued)</button>`:'<span class="muted-sm">No more groups to add.</span>'}</div>`,'')}
  if(m.kind==='role-edit'){const r=(data.roles||{})[m.ctx]||{permissions:[],global:false};const byCat={};cat.forEach(p=>{(byCat[p.cat]=byCat[p.cat]||[]).push(p)});const perms=Object.entries(byCat).map(([c,ps])=>`<div class="perm-group"><b>${esc(c)}</b>${ps.map(p=>`<label class="perm-cbl"><input type="checkbox" class="perm-cb" value="${esc(p.id)}" ${(r.permissions||[]).includes(p.id)?'checked':''}> ${esc(p.label)}</label>`).join('')}</div>`).join('');return wrap(m.ctx?`Edit role — ${esc(m.ctx)}`:'New role',`<div class="form-grid"><div class="field"><label>Role key</label><input id="role-name" value="${esc(m.ctx||'')}" ${m.ctx?'readonly':''}></div><div class="field"><label>Display label</label><input id="role-label" value="${esc(r.label||m.ctx||'')}"></div></div><label class="perm-cbl"><input type="checkbox" id="role-global" ${r.global?'checked':''}> Global scope (all branches)</label><div class="perm-catalog">${perms}</div><p class="muted-sm">A role may not combine two segregated permissions. Queued for authorisation.</p>`,`<button class="primary" onclick="submitRole()">Submit for authorisation</button>`)}
  if(m.kind==='group-edit'){const g=(data.groups||{})[m.ctx]||{roles:[]};const roleCbs=Object.keys(data.roles||{}).map(r=>`<label class="perm-cbl"><input type="checkbox" class="grole-cb" value="${esc(r)}" ${(g.roles||[]).includes(r)?'checked':''}> ${esc(r)}</label>`).join('');return wrap(m.ctx?`Edit group — ${esc(m.ctx)}`:'New group',`<div class="form-grid"><div class="field"><label>Group name</label><input id="group-name" value="${esc(m.ctx||'')}" ${m.ctx?'readonly':''}></div><div class="field"><label>Branch</label><select id="group-branch">${['All Branches',...branches].map(b=>`<option ${b===(g.branch||'All Branches')?'selected':''}>${esc(b)}</option>`).join('')}</select></div></div><div class="field"><label>Description</label><input id="group-desc" value="${esc(g.description||'')}"></div><div class="perm-group"><b>Roles granted by this group</b>${roleCbs}</div>`,`<button class="primary" onclick="submitGroup()">Submit for authorisation</button>`)}
  return wrap('Administration','','')}
function applyState(j){if(!j)return;if(j.data)data=j.data;if(Array.isArray(j.perms))state.perms=j.perms;if(typeof j.global==='boolean')state.global=j.global;if(j.role)state.role=j.role;if(j.branch)state.branch=j.branch;if(j.name)state.user=j.name;if(j.roleLabel)state.roleLabel=j.roleLabel;if(j.initials)state.initials=j.initials;if(j.permCatalog)state.permCatalog=j.permCatalog;if('sms' in j)state.sms=j.sms;if('customerStats' in j)state.customerStats=j.customerStats;if(Array.isArray(j.branches)&&j.branches.length)branches=j.branches;if('adminDirect' in j)state.adminDirect=j.adminDirect}
function audit(){return modulePage('audit','Complete Audit Trail',['Date & time','Action','Reference','Maker','Role','Branch','Remarks'],data.audit,{eyebrow:'COMPLIANCE & ACCOUNTABILITY'})}
function leaves(v){return parseInt(String(v).replace(/[^0-9]/g,''),10)||0}
function canSubmitVault(){return has('vault.submit')}
function canAuthoriseVault(){return has('vault.authorise')}
function cylinder(fill,cls,pctLabel,side){return `<div class="cylinder ${cls}" role="button" tabindex="0" title="Click to view all ${side==='vault'?'vault batches':'inventory ranges'}" onclick="openStock('${side}')" onkeydown="if(event.key==='Enter'||event.key===' '){event.preventDefault();openStock('${side}')}"><div class="cyl-rim"></div><div class="cyl-glass"><div class="cyl-liquid" style="height:${Math.min(100,Math.max(fill,4))}%"><span class="cyl-surface"></span></div></div><div class="cyl-pct">${pctLabel}</div><div class="cyl-hint">View details</div></div>`}
function openStock(side){state.modal={type:'stock',side};render()}
function stockModal(){const isVault=state.modal.side==='vault';const headers=isVault?['Reference','Destination branch','Book type','Serial range','Quantity','Status','Dispatched']:['Reference','Branch','Book type','Serial range','Total','Available','Status'];const rows=isVault?(data.vault||[]):data.inventory;const title=isVault?'Head-Office Vault — cheque stock':'Branch Inventory — cheque ranges';const sub=isVault?'Every cheque batch held in the vault, with its serial range and reconciliation status.':'Every registered cheque serial range currently available in branch inventory.';const count=rows.filter(allowed).length;return `<div class="modal-backdrop"><div class="modal stock-modal"><h2>${title}</h2><p>${sub} Showing <b>${count}</b> record${count===1?'':'s'} in your scope.</p>${table(headers,rows)}<div class="modal-actions"><button class="ghost" onclick="state.modal=null;render()">Close</button></div></div></div>`}
function batchBadge(s){const map={'Submitted to Head Office':'pending','Sent for Printing':'draft','In Head-Office Vault':'issued','In Transit to Branch':'pending','Pending Branch Authorisation':'pending','In Branch Vault':'active'};return `<span class="badge ${map[s]||'draft'}">${esc(s)}</span>`}
function vault(){const all=data.printBatches||[];const hoVault=all.filter(b=>b.status==='In Head-Office Vault'||b.status==='In Transit to Branch');const branchVault=all.filter(b=>b.status==='In Branch Vault');const lv=list=>list.reduce((n,b)=>n+(b.items||[]).reduce((m,i)=>m+(i.leaves||0),0),0);const hoLeaves=lv(hoVault),brLeaves=lv(branchVault);const cap=Math.max(hoLeaves+brLeaves,1);const stage=`<div class="vault-stage"><div class="vault-side">${cylinder(Math.round(hoLeaves/cap*100),'from-ho',hoLeaves.toLocaleString(),'vault')}<div class="vault-cap"><b>Head-Office Vault</b><span>${hoVault.length} batch${hoVault.length===1?'':'es'} · ${hoLeaves.toLocaleString()} leaves</span></div></div><div class="vault-mid"><div class="vault-arrow">→</div><span class="vault-mid-label">Print → HO vault → Branch</span><span class="vault-mid-sub">Itemised batch flow</span></div><div class="vault-side">${cylinder(Math.round(brLeaves/cap*100),'to-inv',brLeaves.toLocaleString(),'inventory')}<div class="vault-cap"><b>Branch Vault</b><span>${branchVault.length} batch${branchVault.length===1?'':'es'} · ${brLeaves.toLocaleString()} leaves</span></div></div></div>`;const rows=all.map(b=>{const nl=(b.items||[]).reduce((m,i)=>m+(i.leaves||0),0);return `<tr><td><b>${esc(b.id)}</b></td><td>${esc(b.branch)}</td><td>${(b.items||[]).length} book(s) · ${nl} leaves</td><td>${batchBadge(b.status)}</td><td>${esc((b.log&&b.log[0]&&b.log[0][0])||b.createdAt||'')}</td><td class="admin-actions"><button class="ghost xs" onclick="openBatch('${esc(b.id)}')">Open</button></td></tr>`}).join('')||'<tr><td colspan="6" class="empty">No print batches yet.</td></tr>';const toolbar=`<div class="module-toolbar"><span class="module-summary">${all.length} batch${all.length===1?'':'es'} in the production pipeline</span>${has('vault.submit')?`<button class="primary" onclick="openNewBatch()">＋ New print batch</button>`:''}</div>`;const list=`<section class="card wide-card"><div class="card-head"><div><h3>Cheque production batches</h3><small>Requisitions flow branch → head office → printing → head-office vault → branch vault, itemised</small></div></div><div class="table-wrap"><table><thead><tr><th>Batch</th><th>Branch</th><th>Contents</th><th>Status</th><th>Updated</th><th></th></tr></thead><tbody>${rows}</tbody></table></div></section>`;return shell(stage+toolbar+list,'Vault & Cheque Production','SECURE STOCK CONTROL')}
async function batchPost(act,body,msg){try{const r=await fetch('/api/batch/'+act,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body||{})});const j=await r.json().catch(()=>({}));if(!r.ok)throw new Error(j.error||'Action failed.');if(j.data)data=j.data;state.modal=null;toast(msg)}catch(e){toast(e.message||'Action failed.')}render()}
function batchAct(id,act,msg){const q={print:'Mark this batch as sent for printing?',dispatch:'Dispatch this batch to the branch?',transfer:'Transfer this batch to the branch vault?',receive:'Confirm receipt of this batch at the branch?',accept:'Authorise this batch into the branch vault? Customers will be notified by SMS.',authorise:'Authorise this batch into the branch vault? Customers will be notified by SMS.',reject:'Return this batch to head office?'};confirmAction(q[act]||'Proceed with this action?',()=>batchPost(act,{id},msg))}
function openNewBatch(){state.modal={type:'newbatch'};render()}
function newBatchModal(){const reqs=(data.requests||[]).filter(r=>r[5]==='Authorized').filter(allowed);const rows=reqs.length?reqs.map(r=>`<label class="pick-row"><input type="checkbox" class="pb-req" value="${esc(r[0])}"><span><b>${esc(r[0])}</b> — ${esc(r[2])} · ${esc(r[1])} · ${esc(r[4])} · ${esc(r[3])}</span></label>`).join(''):'<p class="muted-sm">No authorised requisitions available to batch. Raise and authorise cheque-book requests first.</p>';return `<div class="modal-backdrop"><div class="modal modal-lg"><h2>New print batch</h2><p>Select authorised cheque-book requisitions to send to head office for printing. All must be from the same branch.</p><div class="pick-list">${rows}</div><div class="modal-actions"><button class="ghost" onclick="state.modal=null;render()">Cancel</button><button class="primary" onclick="submitBatch()">Submit to head office</button></div></div></div>`}
function submitBatch(){const requests=[...document.querySelectorAll('.pb-req:checked')].map(c=>c.value);if(!requests.length){toast('Select at least one requisition.');return}batchPost('submit',{requests},'Print batch submitted to head office.')}
function openBatch(id){state.modal={type:'batch',id};render()}
function batchModal(){const b=(data.printBatches||[]).find(x=>x.id===state.modal.id);if(!b){state.modal=null;return ''}const itemsRows=(b.items||[]).map(it=>`<tr><td><b>${esc(it.customer)}</b><br><span class="muted-sm">${esc(it.account)}</span></td><td>${esc(it.size)}</td><td>${it.serialStart?`${esc(it.serialStart)} – ${esc(it.serialEnd)}`:'<span class="muted-sm">—</span>'}</td><td>${esc(it.phone||'—')}</td></tr>`).join('');const s=b.status;const acts=[];const exp=`<button class="secondary" onclick="exportBatchCsv('${b.id}')">⬇ CSV</button><button class="secondary" onclick="exportBatchPdf('${b.id}')">⬇ PDF</button>`;if(s==='Submitted to Head Office'&&has('vault.dispatch'))acts.push(exp,`<button class="primary" onclick="batchAct('${b.id}','print','Sent for printing.')">Mark sent for printing</button>`);if(s==='Sent for Printing'&&has('vault.dispatch'))acts.push(exp,`<button class="primary" onclick="openSerialise('${b.id}')">Enter serials & receive</button>`);if(s==='In Head-Office Vault'&&has('vault.dispatch'))acts.push(`<button class="primary" onclick="batchAct('${b.id}','transfer','Batch transferred to branch.')">Transfer to branch</button>`);if(s==='In Transit to Branch'&&has('vault.submit'))acts.push(`<button class="primary" onclick="batchAct('${b.id}','confirm','Receipt confirmed; awaiting authorisation.')">Confirm receipt</button>`);if(s==='Pending Branch Authorisation'&&has('vault.authorise')){if(b.maker===state.user)acts.push('<span class="vault-note">You confirmed receipt — another officer must authorise into the vault.</span>');else acts.push(`<button class="ghost danger" onclick="batchAct('${b.id}','reject','Batch returned to head office.')">Return to HO</button><button class="primary" onclick="batchAct('${b.id}','accept','Batch accepted into the branch vault.')">Authorise into vault ✓</button>`)}const hist=(b.log||[]).slice(0,4).map(l=>`<div class="detail-row"><span>${esc(l[0])}</span><b>${esc(l[2])} — ${esc(l[1])}</b></div>`).join('');return `<div class="modal-backdrop"><div class="modal modal-lg"><h2>${esc(b.id)} — ${esc(b.branch)}</h2><p>${batchBadge(s)} · ${(b.items||[]).length} cheque book(s)</p><div class="table-wrap"><table><thead><tr><th>Customer</th><th>Book</th><th>Serial range</th><th>Phone</th></tr></thead><tbody>${itemsRows}</tbody></table></div>${hist?`<div class="detail-list" style="margin-top:14px">${hist}</div>`:''}<div class="modal-actions">${acts.join('')}<button class="ghost" onclick="state.modal=null;render()">Close</button></div></div></div>`}
function openSerialise(id){state.modal={type:'serialise',id};render()}
function serialiseModal(){const b=(data.printBatches||[]).find(x=>x.id===state.modal.id);if(!b){state.modal=null;return ''}const rows=(b.items||[]).map(it=>`<div class="field"><label>${esc(it.customer)} — ${esc(it.size)} (${it.leaves} leaves)</label><input class="ser-in" data-req="${esc(it.reqRef)}" inputmode="numeric" maxlength="6" placeholder="Start serial e.g. 000100" value="${esc(it.serialStart||'')}"></div>`).join('');return `<div class="modal-backdrop"><div class="modal modal-lg"><h2>Enter serials — ${esc(b.id)}</h2><p>Type the printer's <b>start serial</b> for each cheque book. The end serial is computed automatically (start + leaves − 1) and zero-padded to 6 digits. Receiving moves the batch into the head-office vault.</p>${rows}<div class="modal-actions"><button class="ghost" onclick="state.modal=null;render()">Cancel</button><button class="primary" onclick="submitSerials('${b.id}')">Receive into head-office vault</button></div></div></div>`}
function submitSerials(id){const serials={};document.querySelectorAll('.ser-in').forEach(i=>{serials[i.dataset.req]=i.value.trim()});batchPost('receive',{id,serials},'Serials recorded; batch received into head-office vault.')}
function exportBatchCsv(id){const b=(data.printBatches||[]).find(x=>x.id===id);if(!b)return;const rows=(b.items||[]).map(it=>[b.id,b.branch,it.reqRef,it.account,it.customer,it.size,it.leaves,it.serialStart||'',it.serialEnd||'',it.phone||'']);exportCsv('print-batch-'+b.id,['Batch','Branch','Requisition','Account','Customer','Book size','Leaves','Serial start','Serial end','Phone'],rows)}
function doPrint(html){let host=document.getElementById('print-host');if(!host){host=document.createElement('div');host.id='print-host';document.body.appendChild(host)}host.innerHTML=html;document.body.classList.add('printing');window.print();setTimeout(()=>{document.body.classList.remove('printing');host.innerHTML=''},600)}
function printSheet(title,subtitleHtml,bodyHtml){return `<div class="print-sheet"><div class="print-head">${LOGO}<div><h1>Akuapem Community Bank PLC</h1><p class="print-tag">Your Financial Partner With Flexible Solutions</p></div></div><h2>${esc(title)}</h2>${subtitleHtml?`<p class="print-sub">${subtitleHtml}</p>`:''}${bodyHtml}<p class="print-foot">Generated ${esc(new Date().toLocaleString())} · Akuapem Community Bank PLC</p></div>`}
function exportBatchPdf(id){const b=(data.printBatches||[]).find(x=>x.id===id);if(!b)return;const rows=(b.items||[]).map((it,i)=>`<tr><td>${i+1}</td><td>${esc(it.customer)}</td><td>${esc(it.account)}</td><td>${esc(it.size)}</td><td>${esc(it.serialStart?it.serialStart+' – '+it.serialEnd:'—')}</td><td>${esc(it.phone||'')}</td></tr>`).join('');const sub=`Batch <b>${esc(b.id)}</b> · Branch: <b>${esc(b.branch)}</b> · Status: ${esc(b.status)}`;const body=`<table><thead><tr><th>#</th><th>Customer</th><th>Account</th><th>Book</th><th>Serial range</th><th>Phone</th></tr></thead><tbody>${rows}</tbody></table><p>Total: ${(b.items||[]).length} cheque book(s).</p>`;doPrint(printSheet('Cheque Printing Batch',sub,body))}
function printReturns(){const f=retFilter();const rows=returnsRows();const tot=rows.reduce((a,g)=>({requests:a.requests+g.requests,issued:a.issued+g.issued,notified:a.notified+g.notified,destroyed:a.destroyed+g.destroyed}),{requests:0,issued:0,notified:0,destroyed:0});const sub=`Period: <b>${esc(f.from||'—')}</b> to <b>${esc(f.to||'—')}</b> · Scope: <b>${esc(state.global?'All branches':state.branch)}</b>`;const body=`<table><thead><tr><th>Branch</th><th>Requests received</th><th>Books issued</th><th>Notifications</th><th>Destroyed</th></tr></thead><tbody>${rows.map(g=>`<tr><td>${esc(g.branch)}</td><td>${g.requests}</td><td>${g.issued}</td><td>${g.notified}</td><td>${g.destroyed}</td></tr>`).join('')}<tr><td><b>Total</b></td><td><b>${tot.requests}</b></td><td><b>${tot.issued}</b></td><td><b>${tot.notified}</b></td><td><b>${tot.destroyed}</b></td></tr></tbody></table>`;doPrint(printSheet('Branch Returns',sub,body))}
function itemisedVaultView(){const rows=(data.vaultItems||[]).filter(allowed);const canReceive=has('vault.submit')||has('vault.authorise');const canDispatch=has('vault.dispatch');const body=rows.length?rows.map(v=>`<tr><td>${esc(v[0])}</td><td>${esc(v[1])}</td><td>${esc(v[2])}</td><td>${esc(v[3])}</td><td>${esc(v[4])}</td><td>${esc(v[5])}</td><td>${badge(v[6])}</td><td>${esc(v[7])}</td><td>${v[6]==='Awaiting Confirmation'&&canReceive?`<button class="ghost xs" onclick="receiveItem('${esc(v[0])}')">Receive &amp; notify</button>`:''}</td></tr>`).join(''):`<tr><td colspan="9" class="empty">No itemised customer cheques in your scope.</td></tr>`;return `<section class="card wide-card" style="margin-top:18px"><div class="card-head"><div><h3>Itemised customer cheques</h3><small>Each entry is one customer's cheque with their linked phone; receiving it sends an SMS that it is ready for collection</small></div>${canDispatch?`<button class="primary" onclick="openDispatchItem()" style="margin:14px 18px 0 0">＋ Dispatch itemised cheque</button>`:''}</div><div class="table-wrap"><table><thead><tr><th>Reference</th><th>Customer</th><th>Account</th><th>Phone</th><th>Branch</th><th>Request</th><th>Status</th><th>Dispatched</th><th></th></tr></thead><tbody>${body}</tbody></table></div></section>`}
function openDispatchItem(){state.modal={type:'dispatchItem'};render()}
async function dispatchItem(){const requestRef=val('#di-request');if(!requestRef){toast('Select a requisition.');return}try{const r=await fetch('/api/vault/dispatch-item',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({requestRef})});const j=await r.json().catch(()=>({}));if(!r.ok)throw new Error(j.error||'Unable to dispatch.');data=j.data;state.modal=null;toast('Itemised cheque dispatched to branch vault.')}catch(e){toast(e.message||'Unable to dispatch.')}render()}
async function receiveItem(ref){try{const r=await fetch('/api/vault/receive-item',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({ref})});const j=await r.json().catch(()=>({}));if(!r.ok)throw new Error(j.error||'Unable to receive.');data=j.data;const s=j.sms||{};toast(s.ok?'Received — customer notified by SMS.':`Received — SMS ${s.detail||'not sent'}.`)}catch(e){toast(e.message||'Unable to receive.')}render()}
function vaultModal(){const canPush=has('vault.dispatch');const canSubmit=canSubmitVault();const canAuth=canAuthoriseVault();const meta=data.vaultMeta||{};const scoped=(data.vault||[]).filter(allowed);const awaiting=scoped.filter(v=>v[5]==='Awaiting Confirmation');const pending=scoped.filter(v=>v[5]==='Pending Authorisation');const branchSel=state.global?`<select data-field="branch">${branches.map(b=>`<option ${b===(branches.includes(state.branch)?state.branch:branches[0])?'selected':''}>${b}</option>`).join('')}</select>`:`<input data-field="branch" value="${esc(state.branch)}" readonly>`;
  const submit=canSubmit?`<div class="vault-section"><h4>① Reconcile &amp; submit</h4><p class="sub">Reconcile the physical hard copies against each vault record, then submit it for second-officer authorisation.</p>${awaiting.length?awaiting.map(v=>`<div class="vault-item"><div class="vault-item-info"><b>${esc(v[0])}</b><span>${esc(v[1])} · ${esc(v[2])} · ${esc(v[3])} · ${esc(v[4])}</span></div><label class="vault-chk"><input type="checkbox" onchange="this.closest('.vault-item').querySelector('.act-btn').disabled=!this.checked"> Hard copies received &amp; reconciled</label><button class="primary act-btn" disabled onclick="submitVault('${esc(v[0])}')">Submit →</button></div>`).join(''):`<p class="empty-note">No batches are awaiting reconciliation in your scope.</p>`}</div>`:'';
  const authorise=canAuth?`<div class="vault-section"><h4>② Authorise into inventory</h4><p class="sub">A second officer confirms the reconciliation and releases the stock into branch inventory. The submitting officer cannot authorise their own batch.</p>${pending.length?pending.map(v=>{const m=meta[v[0]]||{};const ownMaker=m.maker&&m.maker===state.user;return `<div class="vault-item"><div class="vault-item-info"><b>${esc(v[0])}</b><span>${esc(v[1])} · ${esc(v[3])} · ${esc(v[4])}</span><span class="vault-maker">Submitted by ${esc(m.maker||'—')}${m.submitted?` · ${esc(m.submitted)}`:''}</span></div><div class="vault-actions">${ownMaker?`<span class="vault-note">You submitted this — a different officer must authorise.</span>`:`<button class="ghost" onclick="rejectVault('${esc(v[0])}')">Reject</button><button class="primary" onclick="authoriseVault('${esc(v[0])}')">Authorise ✓</button>`}</div></div>`}).join(''):`<p class="empty-note">No batches are pending authorisation in your scope.</p>`}</div>`:'';
  const dispatch=canPush?`<div class="vault-section"><h4>⬆ Dispatch from head office</h4><p class="sub">Register printed cheque stock and push it to a branch vault for confirmation.</p><form id="vault-push-form" onsubmit="return false" class="form-grid"><div class="field"><label>Destination branch</label>${branchSel}</div><div class="field"><label>Cheque book type</label><input data-field="type" value="ACB Standard"></div><div class="field"><label>Start serial</label><input data-field="start" value="180001"></div><div class="field"><label>End serial</label><input data-field="end" value="180500"></div></form><div class="form-actions"><button class="primary" onclick="pushVault()">Push to branch vault →</button></div></div>`:'';
  return `<div class="modal-backdrop"><div class="modal vault-modal"><h2>Vault transfer</h2><p>Cheque stock moves from vault to inventory under maker–checker control. Every step is recorded in the audit trail.</p>${submit}${authorise}${dispatch}${!submit&&!authorise&&!dispatch?'<p class="empty-note">Your role has no vault transfer permissions.</p>':''}<div class="modal-actions"><button class="ghost" onclick="state.modal=null;render()">Close</button></div></div></div>`}
function notifications(){if(!has('notifications.view'))return shell(`<div class="denied"><b>Customer alerts restricted</b><br>Your profile does not include permission to view customer alerts.</div>`,'Customer Alerts','CUSTOMER ENGAGEMENT');const rows=(data.notifications||[]);const scoped=rows.filter(allowed);return shell(`<div class="notice">Alerts are dispatched automatically when cheque stock is accepted into a branch and when a cheque book is issued and ready for collection. These are recorded here; connect an SMS/email gateway to deliver them to customers.</div><div class="module-toolbar"><span class="module-summary">Showing <strong>${scoped.length}</strong> customer alert${scoped.length===1?'':'s'} within your scope</span></div><section class="card wide-card"><div class="card-head"><div><h3>Customer alert log</h3><small>Automated ready-for-collection and stock-arrival notifications</small></div></div>${table(['Reference','Customer','Account','Branch','Channel','Message','Status','Sent'],rows)}</section>`,'Customer Alerts','CUSTOMER ENGAGEMENT')}
function page(){if(state.page==='notifications')return notifications();if(state.page==='vault')return vault();if(state.page==='dashboard')return dashboard();if(state.page.endsWith('-new')&&['request','inventory','issuance'].includes(state.page.replace('-new','')))return form(state.page.replace('-new',''));const maps={request:['Cheque Book Requests',['Reference','Account','Customer','Branch','Book size','Status','Created'],data.requests,{create:{label:'＋ New request'},action:'View'}],inventory:['Cheque Book Inventory & Ranges',['Reference','Branch','Book type','Serial range','Total','Available','Status'],data.inventory,{create:{label:'＋ Register range'},action:'View'}],issuance:['Issuance & Collection',['Reference','Request','Customer','Branch','Serial range','Status','Processed'],data.issuance,{create:{label:'＋ Issue cheque book'},action:'View'}]};if(maps[state.page])return modulePage(state.page,...maps[state.page]);if(state.page==='customers')return customers();if(state.page==='authorization')return authorization();if(state.page==='reports')return reports();if(state.page==='admin')return admin();if(state.page==='audit')return audit();return dashboard()}
function uName(id){return (data.directory&&data.directory[id]&&data.directory[id].name)||id}
function confirmAction(message,fn){state.confirm={message,fn};state.openMenu=null;render()}
function runConfirm(){const fn=state.confirm&&state.confirm.fn;state.confirm=null;render();if(fn)fn()}
function cancelConfirm(){state.confirm=null;render()}
function confirmDialog(){const c=state.confirm;if(!c)return '';return `<div class="modal-backdrop"><div class="modal confirm-modal"><h2>Please confirm</h2><p>${esc(c.message)}</p><div class="modal-actions"><button class="ghost" onclick="cancelConfirm()">Cancel</button><button class="primary" onclick="runConfirm()">Yes, continue</button></div></div></div>`}
function toggleMenu(id){state.openMenu=state.openMenu===id?null:id;render()}
function modal(){const m=state.modal;if(m.type==='dashdetail')return dashDetailModal(m.kind);if(m.type==='destroy'){const rq=(data.requests||[]).find(r=>r[0]===m.ctx)||[];return `<div class="modal-backdrop"><div class="modal"><h2>Destroy uncollected book</h2><p class="muted-sm">This records a destruction certificate and removes the book from the aging bin. Perform under dual control and enter the witnessing officer.</p><div class="detail-list"><div class="detail-row"><span>Request</span><b>${esc(rq[0]||m.ctx)}</b></div><div class="detail-row"><span>Customer</span><b>${esc(rq[2]||'—')}</b></div><div class="detail-row"><span>Branch</span><b>${esc(rq[3]||'—')}</b></div></div><div class="field"><label>Witnessing officer</label><input id="destroy-witness" placeholder="Name of second officer"></div><div class="field"><label>Method</label><select id="destroy-method"><option>Shredded</option><option>Incinerated</option><option>Pulped</option></select></div><div class="modal-actions"><button class="ghost" onclick="state.modal=null;render()">Cancel</button><button class="primary danger" onclick="submitDestroy()">Confirm destruction</button></div></div></div>`}if(m.type==='cert'){const r=(data.destructions||[]).find(x=>x[0]===m.ctx);if(!r)return `<div class="modal-backdrop"><div class="modal"><p>Certificate not found.</p><div class="modal-actions"><button class="primary" onclick="state.modal=null;render()">Close</button></div></div></div>`;return `<div class="modal-backdrop"><div class="modal cert-modal"><div class="cert-sheet"><div class="cert-head"><div class="cert-seal">${LOGO}</div><div><h2>Akuapem Community Bank PLC</h2><p class="cert-sub">Cheque-Book Destruction Certificate</p></div></div><table class="cert-table"><tr><td>Certificate no.</td><td><b>${esc(r[0])}</b></td></tr><tr><td>Request reference</td><td>${esc(r[1])}</td></tr><tr><td>Account</td><td>${esc(r[2])}</td></tr><tr><td>Customer</td><td>${esc(r[3])}</td></tr><tr><td>Branch</td><td>${esc(r[4])}</td></tr><tr><td>Cheque book</td><td>${esc(r[5])}</td></tr><tr><td>Serial range</td><td>${esc(r[6])}</td></tr><tr><td>Method of destruction</td><td>${esc(r[10]||'Shredded')}</td></tr><tr><td>Date</td><td>${esc(r[9])}</td></tr></table><p class="cert-note">The cheque book described above was uncollected for over one year and has been destroyed under dual control in accordance with the Bank's cheque-stock policy.</p><div class="cert-sign"><div><div class="cert-line"></div>Destroyed by: ${esc(r[7])}</div><div><div class="cert-line"></div>Witnessed by: ${esc(r[8])}</div></div></div><div class="modal-actions"><button class="ghost" onclick="state.modal=null;render()">Close</button><button class="primary" onclick="doPrintCert()">🖨 Print certificate</button></div></div></div>`}if(m.type==='newbatch')return newBatchModal();if(m.type==='batch')return batchModal();if(m.type==='serialise')return serialiseModal();if(m.type==='dispatchItem'){const reqs=(data.requests||[]).filter(allowed);return `<div class="modal-backdrop"><div class="modal"><h2>Dispatch itemised cheque</h2><p>Select a cheque book requisition. The customer's linked phone number travels with it; when the branch receives the cheque, that customer is alerted by SMS.</p><div class="field"><label>Requisition</label><select id="di-request">${reqs.length?reqs.map(r=>`<option value="${esc(r[0])}">${esc(r[0])} — ${esc(r[2])} · ${esc(r[3])} (${esc(r[5])})</option>`).join(''):'<option value="">No requisitions available</option>'}</select></div><div class="modal-actions"><button class="ghost" onclick="state.modal=null;render()">Cancel</button><button class="primary" onclick="dispatchItem()">Dispatch to branch vault</button></div></div></div>`}if(m.type==='policy')return `<div class="modal-backdrop"><div class="modal"><h2>Login &amp; acceptable use policy</h2><p>This is a private, restricted system of Akuapem Community Bank PLC. By signing in you confirm that you are an authorised user and accept the Bank's Acceptable Use and Information Security Policy.</p><ul class="policy-list"><li>Access is limited to authorised staff using their own credentials; sharing or disclosing credentials is prohibited.</li><li>Every sign-in and action is authenticated and recorded in the audit trail, and access is monitored.</li><li>Information in this system is confidential and must be handled in line with the Bank's data-protection obligations.</li><li>Unauthorised access, use, or disclosure is prohibited and may lead to disciplinary action and prosecution.</li><li>Change your password after first sign-in and never share it with anyone, including IT staff.</li></ul><div class="modal-actions"><button class="primary" onclick="state.modal=null;render()">Close</button></div></div></div>`;if(m.type==='admin')return adminModal();if(m.type==='pw')return `<div class="modal-backdrop"><div class="modal"><h2>Change password</h2><p>Choose a strong password of at least 10 characters.</p><div class="field"><label>Current password</label><input id="pw-current" type="password" autocomplete="current-password"></div><div class="field"><label>New password</label><input id="pw-new" type="password" autocomplete="new-password"></div><div class="field"><label>Confirm new password</label><input id="pw-confirm" type="password" autocomplete="new-password"></div><div class="modal-actions"><button class="ghost" onclick="state.modal=null;render()">Cancel</button><button class="primary" onclick="submitPassword()">Update password</button></div></div></div>`;if(m.type==='vault')return vaultModal();if(m.type==='stock')return stockModal();if(m.type==='detail'){const rows=m.headers.map((h,i)=>`<div class="detail-row"><span>${esc(h)}</span><b>${['Status','State'].includes(h)?badge(m.row[i]):esc(m.row[i])}</b></div>`).join('');return `<div class="modal-backdrop"><div class="modal"><h2>${esc(m.row[0])}</h2><p>Read-only record detail within your permitted branch scope.</p><div class="detail-list">${rows}</div><div class="modal-actions"><button class="primary" onclick="state.modal=null;render()">Close</button></div></div></div>`}if(m.type==='approveTxn'){const it=m.item;const meta=(data.approvalMeta||{})[it[0]]||{};const own=meta.maker&&meta.maker===state.user;const rows=[['Queue ID',it[0]],['Transaction',it[1]],['Reference',it[2]],['Customer / Subject',it[3]],['Branch',it[4]],['Maker',it[5]],['Submitted',it[6]]].map(([h,v])=>`<div class="detail-row"><span>${h}</span><b>${esc(v)}</b></div>`).join('');return `<div class="modal-backdrop"><div class="modal"><h2>Review transaction</h2><p>Confirm the maker's submission. Authorising applies the transaction; rejecting returns it. Both are recorded in the audit trail.</p><div class="detail-list">${rows}</div>${own?`<div class="vault-note" style="margin-top:12px;max-width:none">You submitted this transaction — a different officer with approval rights must authorise it.</div>`:''}<div class="modal-actions"><button class="ghost" onclick="state.modal=null;render()">Cancel</button>${own?'':`<button class="ghost" onclick="rejectTxn('${esc(it[0])}')">Reject</button><button class="primary" onclick="authoriseTxn('${esc(it[0])}')">Authorise ✓</button>`}</div></div></div>`}return `<div class="modal-backdrop"><div class="modal"><h2>Confirm submission</h2><p>This transaction will be captured and routed for maker-checker authorisation, and recorded in the audit trail.</p><div class="field"><label>Remarks (optional)</label><textarea rows="3" placeholder="Add a comment for the audit record"></textarea></div><div class="modal-actions"><button class="ghost" onclick="state.modal=null;render()">Cancel</button><button class="primary" onclick="confirmModal()">Confirm submission</button></div></div></div>`}
function openPolicy(){state.modal={type:'policy'};render()}
function render(){app.innerHTML=state.logged?page():login()+(state.modal&&state.modal.type==='policy'?modal():'')}
function go(p){state.page=p;render()}
async function signIn(){const staffId=document.querySelector('#login-staff').value.trim();const password=document.querySelector('#login-password').value;if(location.protocol==='file:'){state.role='Branch Operations';state.branch='Nsawam Branch';state.user='Yaw Sarpong';state.perms=['request.create','inventory.create','issuance.create','stop.create','returns.create','vault.submit'];state.global=false;state.initials='YS';state.logged=true;return render()}try{const r=await fetch('/api/session',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({staffId,password})});const j=await r.json().catch(()=>({}));if(!r.ok)throw new Error(j.error||'Sign-in failed.');applyState(j);state.loginError='';state.logged=true;render()}catch(e){state.loginError=e.message||'Unable to sign in.';render()}}
async function logout(){try{if(location.protocol!=='file:')await fetch('/api/logout',{method:'POST'})}catch(e){}state.logged=false;state.modal=null;state.user='';render()}
function setBranch(v){state.branch=v==='All Branches'?'All Branches':v;render()}
function openForm(k){state.prefill=null;state.page=k+'-new';render()}
function submitForm(k){const fields={};document.querySelectorAll('#txn-form [data-field]').forEach(el=>{fields[el.dataset.field]=el.value.trim()});state.modal={type:'submit',key:k,fields};render()}
function rowAction(k,i){const md=moduleData(k);if(!md)return;const row=md.rows.filter(allowed)[i];if(!row)return;if(k==='authorization'){state.modal={type:'approveTxn',item:row};render();return}state.modal={type:'detail',key:k,headers:md.headers,row};render()}
async function confirmModal(){const m=state.modal;const k=m.key;const fields=m.fields||{};state.modal=null;try{if(location.protocol!=='file:'){const result=await fetch('/api/transactions',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({module:k,fields})});const json=await result.json().catch(()=>({}));if(!result.ok)throw new Error(json.error||'The request was rejected.');data=json.data}toast('Transaction submitted for authorisation.');state.page=k}catch(error){toast(error.message||'Unable to save. Please try again.')}render()}
async function approvalAction(path,id,okMsg){try{const r=await fetch(path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({ref:id})});const j=await r.json().catch(()=>({}));if(!r.ok)throw new Error(j.error||'Action failed.');data=j.data;state.modal=null;toast(okMsg)}catch(e){toast(e.message||'Action failed.')}render()}
function authoriseTxn(id){return approvalAction('/api/authorizations/authorise',id,'Transaction authorised and applied.')}
function rejectTxn(id){return approvalAction('/api/authorizations/reject',id,'Transaction rejected and returned.')}
function openVault(){state.modal={type:'vault'};render()}
async function vaultAction(path,ref,okMsg){try{const r=await fetch(path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({ref})});const j=await r.json().catch(()=>({}));if(!r.ok)throw new Error(j.error||'Action failed.');data=j.data;state.modal=null;toast(okMsg)}catch(e){toast(e.message||'Action failed.')}render()}
function submitVault(ref){return vaultAction('/api/vault/submit',ref,'Batch reconciled and submitted for authorisation.')}
function authoriseVault(ref){return vaultAction('/api/vault/authorise',ref,'Batch authorised and moved into branch inventory.')}
function rejectVault(ref){return vaultAction('/api/vault/reject',ref,'Batch returned for re-reconciliation.')}
async function pushVault(){const fields={};document.querySelectorAll('#vault-push-form [data-field]').forEach(el=>{fields[el.dataset.field]=el.value.trim()});try{const r=await fetch('/api/vault/push',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({role:state.role,branch:state.branch,fields})});const j=await r.json().catch(()=>({}));if(!r.ok)throw new Error(j.error||'Unable to dispatch batch.');data=j.data;state.modal=null;toast('Cheque stock dispatched to branch vault, awaiting confirmation.')}catch(e){toast(e.message||'Unable to dispatch batch.')}render()}
function filterTable(v){document.querySelectorAll('tbody tr').forEach(row=>row.style.display=row.innerText.toLowerCase().includes(v.toLowerCase())?'':'none')}
async function customerSearch(){const q=val('#customer-q');const box=document.querySelector('#customer-result');if(q.length<2){box.innerHTML='<p class="empty-note">Type at least 2 characters.</p>';return}box.innerHTML='<p class="empty-note">Searching…</p>';try{const r=await fetch('/api/customers/search?q='+encodeURIComponent(q));const j=await r.json().catch(()=>({}));if(!r.ok)throw new Error(j.error||'Search failed.');state.custResults=j.results||[];const canReq=has('request.create');const rows=state.custResults.map(c=>`<tr><td><b>${esc(c.account)}</b></td><td>${esc(c.name)}</td><td>${esc(c.phone||'—')}</td><td>${esc(c.branch||'—')}</td><td>${esc(c.type||'—')}</td><td>${c.status?badge(c.status):'—'}</td><td>${canReq?`<button class="ghost xs" onclick="useCustomer('${esc(c.account)}')">Use for requisition</button>`:''}</td></tr>`).join('');box.innerHTML=state.custResults.length?`<section class="card wide-card" style="margin-top:18px"><div class="card-head"><div><h3>Results</h3><small>Showing ${state.custResults.length} match${state.custResults.length===1?'':'es'} (max 25)</small></div></div><div class="table-wrap"><table><thead><tr><th>Account</th><th>Customer</th><th>Phone</th><th>Branch</th><th>Type</th><th>Status</th><th></th></tr></thead><tbody>${rows}</tbody></table></div></section>`:'<div class="card" style="margin-top:18px"><p class="empty-note">No customer found. If this is a new customer, create the cheque book request directly — they will be added to the database once it is authorised.</p></div>'}catch(e){box.innerHTML=`<p class="empty-note">${esc(e.message||'Search failed.')}</p>`}}
function useCustomer(account){const c=(state.custResults||[]).find(x=>x.account===account);if(!c)return;state.prefill={account:c.account,customer:c.name,phone:c.phone||''};state.page='request-new';render()}
async function bootstrap(){try{if(location.protocol!=='file:'){const response=await fetch('/api/state');if(response.ok){const j=await response.json();applyState(j);if(j.role)state.logged=true}}}catch(error){console.info('Running with local demonstration data.')}render()}
bootstrap();
